insert into public.catalog_releases (release_id, country_code, version, status, data_checked_until, notes, source_notes, road_factor, avg_kmh, road_calibrated, road_note, airport_radius_km, previous_release_id) values
  ('NO-4', 'NO', 4, 'bozza', '2026-11-12', 'Quarta versione: tutto NO-3 più musei, parchi e attrazioni in tutta la Norvegia, con le foto; foto anche per i luoghi che non ne avevano.', '[{"label":"Coordinate: OpenStreetMap (Nominatim)","checkedAt":"2026-10-27","license":"ODbL 1.0"},{"label":"Schede delle attrazioni: siti ufficiali e Wikidata P625","checkedAt":"2026-11-06","license":"CC0 1.0 (Wikidata)"},{"label":"Siti ufficiali: Wikidata P856 e verifica manuale","checkedAt":"2026-10-27"},{"label":"Riferimenti Wikidata/Wikipedia/Commons","checkedAt":"2026-10-27","license":"CC0 1.0 (Wikidata)"},{"label":"Confini delle contee: Kartverket","checkedAt":"2026-10-27","note":"licenza da verificare"},{"label":"Porti della rotta costiera: Havila e Hurtigruten","checkedAt":"2026-10-27","note":"coordinate approssimative"},{"label":"Proposte di crociera: siti Havila e Hurtigruten","checkedAt":"2026-10-28","note":"prezzi e date come pubblicati, non tariffe garantite"},{"label":"Tratte traghetto: Entur (orari invernali 2026/27, registro NSR), siti di compagnie ed enti regionali; fergeruter.info solo dove la fonte primaria mancava","checkedAt":"2026-11-09","note":"Tariffe 2026 da verificare per il 2027 (solo Bergen–Flåm ha prezzi 2027). Coordinate solo NSR."},{"label":"Luoghi del nord: coordinate da Wikidata (P625) o OpenStreetMap (Nominatim)","checkedAt":"2026-11-10","license":"CC0 1.0 / ODbL 1.0"},{"label":"Foto: Wikimedia Commons, solo licenze libere, con autore e licenza","checkedAt":"2026-11-10"},{"label":"Consigli: solo da fonti ufficiali (Nasjonale turistveger, Statens vegvesen)","checkedAt":"2026-11-10","note":"Servizi e aperture come pubblicati alla data di lettura: da verificare prima di partire"},{"label":"Musei, parchi e attrazioni: coordinate da Wikidata (P625) o OpenStreetMap (Nominatim); foto di Wikimedia Commons con autore e licenza","checkedAt":"2026-11-12","license":"CC0 1.0 / ODbL 1.0","note":"Testi scritti per l''app, da verificare; nessun prezzo e nessun orario"}]'::jsonb, 1.7, 52, true, 'Tarati il 2026-10-27 su Bergen → Ålesund calcolato con OSRM. Restano stime.', 110, 'NO-3')
