  ('NO-4', 'tusenfryd', 'it', 'TusenFryd', 'Il più grande parco divertimenti della Norvegia, a Vinterbro, fuori Oslo.', 'Vinterbro, circa 20 km dal centro di Oslo.', 'Stagionale: date di agosto da verificare', null, 'Vinterbro, fuori Oslo', 'Biglietti in vendita sul sito; il sito non indica una prenotazione obbligatoria.', 'Parco stagionale: a novembre 2026 il sito lo indica chiuso, con riapertura il 24 aprile 2027. Date e orari di agosto da verificare.', 'Fuori città: circa 20 km dal centro di Oslo secondo il sito ufficiale. Trasferimento e tempi da verificare.'),
  ('NO-4', 'dyreparken', 'it', 'Kristiansand Dyrepark', 'Zoo e parco a tema (villaggio di Cardamomo).', 'Kristiansand.', 'Visitabile in agosto (da verificare)', null, null, null, null, null),
  ('NO-4', 'aurora', 'it', 'Aurora boreale', 'Esperienza da settembre a marzo nel nord del paese.', 'Tromsø e nord.', 'Settembre–marzo', 'Ad agosto le notti sono troppo luminose: non è realistico pianificarla per questo viaggio.', null, null, null, null),
  ('NO-4', 'midnight-sun', 'it', 'Sole di mezzanotte', 'Sole sopra l''orizzonte a mezzanotte a nord del Circolo Polare.', 'Nord della Norvegia.', 'Fine maggio–luglio (varia con la latitudine)', 'Ad agosto il periodo è in genere concluso; restano notti molto chiare. Verificare le date per la latitudine scelta.', null, null, null, null),
