  ('NO-4', 'bodo', 'it', 'Bodø', 'Capoluogo del Nordland, nella regione di Salten: è la porta delle Lofoten, con il traghetto per Moskenes, l''aeroporto e il capolinea della ferrovia del Nordland.', 'In aereo, in treno (capolinea della linea del Nordland) o in auto; dal porto partono i traghetti per le Lofoten (vedi Trasporti via mare).', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-4', 'kjerringoy', 'it', 'Kjerringøy, antico emporio', 'Museo all''aperto in un antico emporio commerciale sulla costa a nord di Bodø; fa parte del museo del Nordland.', 'In auto da Bodø verso nord; lungo la strada c''è un breve traghetto, con orari da verificare.', 'Apertura stagionale: da verificare sul sito del museo', null, null, null, null, null),
  ('NO-4', 'luftfartsmuseum', 'it', 'Museo norvegese dell''aviazione', 'Museo nazionale dell''aviazione, aperto nel 1994: è il più grande dei paesi nordici (circa 10.000 m²), in un edificio a forma di elica, con aerei civili e militari.', 'A Bodø, in città.', 'Tutto l''anno; orari da verificare sul sito del museo', null, null, null, null, null),
  ('NO-4', 'keiservarden', 'it', 'Keiservarden', 'Altopiano panoramico a 366 m sopra Bodø, sul colle Veten. Il nome ricorda l''imperatore tedesco Guglielmo II che, secondo la tradizione, vi salì nel 1899.', 'A piedi su sentiero dai dintorni di Bodø; punto di partenza e tempi da verificare.', 'Estate e inizio autunno; con neve o ghiaccio il sentiero cambia', null, null, null, null, null),
  ('NO-4', 'moskenes', 'it', 'Moskenes', 'Villaggio sull''isola di Moskenesøya, subito a nord di Sørvågen, dove attracca il traghetto da Bodø. La chiesa bianca in legno è lungo la E10.', 'Traghetto da Bodø (vedi Trasporti via mare) oppure in auto sulla E10.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-4', 'sorvagen', 'it', 'Sørvågen', 'Villaggio di pescatori sull''isola di Moskenesøya, tra Moskenes e Å, lungo la E10.', 'Lungo la E10, la strada delle Lofoten, poco prima di Å.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-4', 'reinebringen', 'it', 'Reinebringen', 'Cima di 484 m sopra Reine, tra le più salite della Norvegia. Si sale su una scalinata in pietra, ripida e faticosa, fino a una vista sul Reinefjord.', 'A piedi da Reine; punto di partenza e parcheggio da verificare.', 'Estate; in autunno, inverno e primavera la salita è sconsigliata per il rischio di sassi e neve', 'Salita ripida e impegnativa, con incidenti e soccorsi in passato: con bambini di 5 e 8 anni va valutata con molta prudenza. L''area di sosta Reinehalsen, ai piedi del monte, dà una bella vista senza salire.', null, null, null, null),
  ('NO-4', 'kvalvika', 'it', 'Kvalvika', 'Baia con due spiagge di sabbia sul lato esterno di Moskenesøya, chiusa tra i monti Ryten e Kjerringa. Non ci arriva nessuna strada.', 'Solo a piedi su sentiero (circa 2 km dal Torsfjorden); punto di partenza e parcheggio da verificare.', 'Estate', 'Il sentiero ha tratti sassosi: da valutare con il bambino di 5 anni.', null, null, null, null),
  ('NO-4', 'ryten', 'it', 'Ryten', 'Monte sull''isola di Moskenesøya, a nord della baia di Kvalvika: dalla cima si vede la spiaggia dall''alto.', 'A piedi su sentiero dai dintorni di Fredvang; punto di partenza, dislivello e tempi da verificare.', 'Estate', 'Escursione di montagna con tratti esposti in cima: da valutare con bambini piccoli.', null, null, null, null),
  ('NO-4', 'fredvang', 'it', 'Fredvang', 'Villaggio di pescatori sull''isola di Moskenesøya, collegato a Flakstadøya da due ponti a sbalzo (Fredvangbruene). È il punto d''accesso ai sentieri per Kvalvika e Ryten.', 'Deviazione dalla E10 attraverso i due ponti di Fredvang.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-4', 'ramberg', 'it', 'Ramberg e la sua spiaggia', 'Villaggio dell''isola di Flakstadøya con una lunga spiaggia di sabbia chiara rivolta a nord. L''area di sosta della strada turistica ha una passerella in legno che porta alla spiaggia.', 'Lungo la E10, la strada delle Lofoten: la spiaggia è accanto alla strada.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-4', 'flakstad-kirke', 'it', 'Chiesa di Flakstad', 'Chiesa rossa in legno a pianta a croce, costruita nel 1780 nel villaggio di Flakstad; ha circa 300 posti.', 'Poco fuori dalla E10, tra Ramberg e Skagsanden.', 'Apertura per le visite da verificare', null, null, null, null, null),
  ('NO-4', 'skagsanden', 'it', 'Spiaggia di Skagsanden', 'Spiaggia di sabbia sull''isola di Flakstadøya, accanto al villaggio di Flakstad, lungo la strada turistica delle Lofoten.', 'Lungo la E10, la strada delle Lofoten: la spiaggia è accanto alla strada.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-4', 'vikten', 'it', 'Vikten', 'Piccolo villaggio sulla costa nord di Flakstadøya, alla fine di una deviazione della strada turistica; c''è un laboratorio di artigianato con lavorazione del vetro.', 'Deviazione dalla E10 (strada 811), a fondo cieco.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-4', 'ballstad', 'it', 'Ballstad', 'Uno dei più grandi villaggi di pescatori delle Lofoten, su una piccola isola all''estremità sud-ovest di Vestvågøya, alla bocca del Buksnesfjorden.', 'Deviazione dalla E10 a sud di Leknes.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-4', 'leknes', 'it', 'Leknes', 'Cittadina al centro di Vestvågøya e capoluogo del comune più popoloso delle Lofoten: negozi e servizi; c''è un piccolo aeroporto.', 'Lungo la E10, la strada delle Lofoten.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-4', 'uttakleiv', 'it', 'Spiaggia di Uttakleiv', 'Spiaggia sul lato esterno di Vestvågøya, in fondo a una delle deviazioni della strada turistica delle Lofoten.', 'Deviazione dalla E10 a nord di Leknes, passando per Haukland; strada a fondo cieco.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-4', 'unstad', 'it', 'Unstad', 'Piccolo borgo in fondo alla baia di Unstadvika, sul lato esterno di Vestvågøya, circondato da monti di 300–650 m. La spiaggia è nota per il surf.', 'Deviazione dalla E10 (strada 992), a fondo cieco, con una galleria.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-4', 'eggum', 'it', 'Eggum', 'Villaggio di pescatori sulla costa nord di Vestvågøya. Accanto ci sono una riserva naturale e un''area di sosta a forma di anfiteatro rivolta all''oceano aperto.', 'Deviazione dalla E10 a Bøstad (strada 994, circa 10 km).', 'Estate; molti vengono qui per il sole di mezzanotte (fino a metà luglio circa: ad agosto il sole tramonta)', null, null, null, null, null),
  ('NO-4', 'borg-lofoten', 'it', 'Borg (Bøstad)', 'Villaggio lungo la E10 al centro di Vestvågøya, accanto alla frazione di Borg con il museo vichingo Lofotr e la chiesa di Borge.', 'Lungo la E10, la strada delle Lofoten.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-4', 'stamsund', 'it', 'Stamsund', 'Villaggio di pescatori sul lato sud di Vestvågøya, affacciato sul Vestfjorden, a circa 12 km da Leknes. È uno scalo della rotta costiera.', 'Deviazione dalla E10 da Leknes.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-4', 'gimsoy', 'it', 'Gimsøya', 'Isola tra Austvågøya e Vestvågøya, attraversata dalla E10 con due ponti. Sul lato nord ci sono spiagge e una piccola chiesa.', 'Lungo la E10, la strada delle Lofoten; il giro dell''isola è una deviazione.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-4', 'kabelvag', 'it', 'Kabelvåg', 'Villaggio sulla costa sud di Austvågøya, a circa 5 km da Svolvær. Nella vicina Storvågan ci sono l''acquario, il museo delle Lofoten e la galleria Espolin.', 'Lungo la E10, la strada delle Lofoten, a sud-ovest di Svolvær.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-4', 'lofotakvariet', 'it', 'Acquario delle Lofoten', 'Acquario di acqua salata a Storvågan, vicino a Kabelvåg, qui dal 1989: vasche con la vita marina delle Lofoten e bacini per foche e lontre.', 'A Storvågan, poco fuori dalla E10 vicino a Kabelvåg.', 'Orari e giorni di apertura da verificare', null, null, null, null, null),
  ('NO-4', 'lofotmuseet', 'it', 'Museo delle Lofoten', 'Museo nell''antico villaggio di pescatori di Storvågan: la casa padronale del 1815, le rorbuer, le rimesse con le barche del Nordland e mostre sulla pesca alle Lofoten.', 'A Storvågan, poco fuori dalla E10 vicino a Kabelvåg.', 'Orari e giorni di apertura da verificare', null, null, null, null, null),
  ('NO-4', 'galleri-espolin', 'it', 'Galleria Espolin', 'Galleria d''arte a Storvågan, vicino a Kabelvåg, nata nel 1992 per le opere di Kaare Espolin Johnson.', 'A Storvågan, poco fuori dalla E10 vicino a Kabelvåg.', 'Orari e giorni di apertura da verificare', null, null, null, null, null),
  ('NO-4', 'lofotkatedralen', 'it', 'Chiesa di Vågan («cattedrale delle Lofoten»)', 'Grande chiesa gialla in legno a pianta a croce, costruita nel 1898 a Kabelvåg e detta «cattedrale delle Lofoten».', 'Lungo la E10, la strada delle Lofoten, a Kabelvåg.', 'Apertura per le visite da verificare', null, null, null, null, null),
  ('NO-4', 'svolvaergeita', 'it', 'Svolværgeita', 'Pinnacolo di roccia alto 150 m sul fianco del monte Fløyfjellet, sopra Svolvær: è una meta di arrampicata, salita per la prima volta nel 1910.', 'Si vede da Svolvær; la salita è una via di arrampicata.', 'Estate', 'La cima è per arrampicatori con guida: con i bambini si guarda dal basso.', null, null, null, null),
  ('NO-4', 'krigsminnemuseum', 'it', 'Museo della guerra delle Lofoten', 'Museo sulla seconda guerra mondiale a Svolvær, aperto nel 1996, dedicato soprattutto ai fatti delle Lofoten e del nord durante l''occupazione tedesca (1940–1945).', 'A Svolvær, in centro.', 'Orari e giorni di apertura da verificare', 'Temi di guerra: da valutare per i bambini.', null, null, null, null),
  ('NO-4', 'trollfjord', 'it', 'Trollfjord', 'Fiordo lungo 2 km che entra nell''isola di Austvågøya dallo stretto di Raftsundet, con un ingresso stretto e pareti ripide.', 'Solo via mare: escursioni in barca da Svolvær; anche le navi della rotta costiera vi entrano in estate. Orari e prezzi da verificare.', 'Estate', null, null, null, null, null),
  ('NO-4', 'skrova', 'it', 'Skrova', 'Piccola isola con un villaggio di pescatori nel Vestfjorden, a sud di Austvågøya.', 'Solo via mare da Svolvær; collegamento e orari da verificare.', 'Estate', null, null, null, null, null),
  ('NO-4', 'laukvik', 'it', 'Laukvik', 'Villaggio di pescatori sulla costa nord-ovest di Austvågøya, affacciato sul Mare di Norvegia.', 'Deviazione dalla E10 sul lato nord di Austvågøya.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-4', 'vaeroy', 'it', 'Værøy', 'Isola e comune delle Lofoten, a sud di Moskenesøya. Il centro è il villaggio di Sørland, intorno al porto.', 'Solo via mare o in aereo; i traghetti partono da Bodø e da Moskenes (vedi Trasporti via mare), orari da verificare.', 'Estate', null, null, null, null, null),
  ('NO-4', 'rost', 'it', 'Røst', 'Piccolo comune insulare all''estremità delle Lofoten: di fatto un grande villaggio di pescatori sull''isola di Røstlandet. Le isole vicine ospitano grandi colonie di uccelli marini.', 'Solo via mare o in aereo; i traghetti partono da Bodø (vedi Trasporti via mare), orari da verificare.', 'Estate', null, null, null, null, null),
  ('NO-4', 'fiskevaersmuseum', 'it', 'Museo norvegese dei villaggi di pescatori', 'Museo dedicato alla pesca norvegese nel villaggio di Å: gli edifici del villaggio, fra cui la fabbrica dell''olio di fegato di merluzzo.', 'A Å, dove finisce la E10.', 'Orari e giorni di apertura da verificare', null, null, null, null, null),
  ('NO-4', 'torrfiskmuseum', 'it', 'Museo dello stoccafisso delle Lofoten', 'Museo nel villaggio di Å dedicato alla produzione dello stoccafisso, uno dei più antichi prodotti di esportazione della Norvegia.', 'A Å, dove finisce la E10.', 'Orari e giorni di apertura da verificare', null, null, null, null, null),
  ('NO-4', 'sortland', 'it', 'Sortland', 'Cittadina delle Vesterålen e capoluogo del comune omonimo, sullo stretto di Sortlandsundet; qui ha la base nord la Guardia costiera norvegese.', 'Sulla strada tra le Lofoten e Andøya; è anche uno scalo della rotta costiera.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-4', 'stokmarknes', 'it', 'Stokmarknes', 'Cittadina sulla costa nord dell''isola di Hadseløya, capoluogo del comune di Hadsel. Qui è nata la rotta costiera Hurtigruten, e c''è il suo museo.', 'In auto dalle Vesterålen (ponti) o dalle Lofoten con il traghetto Fiskebøl–Melbu; è uno scalo della rotta costiera.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-4', 'hurtigrutemuseet', 'it', 'Museo Hurtigruten', 'Museo della rotta costiera a Stokmarknes, dove la linea è nata. Comprende l''ex nave costiera MS Finnmarken, che si visita.', 'A Stokmarknes, in centro.', 'Orari e giorni di apertura da verificare', null, null, null, null, null),
  ('NO-4', 'melbu', 'it', 'Melbu', 'Villaggio sull''isola di Hadseløya, sulla riva nord dell''Hadselfjorden. Da qui parte il traghetto per Fiskebøl, verso le Lofoten.', 'Traghetto da Fiskebøl (vedi Trasporti via mare) o in auto da Stokmarknes.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-4', 'nyksund', 'it', 'Nyksund', 'Villaggio di pescatori isolato sulla costa nord dell''isola di Langøya, nelle Vesterålen. Si raggiunge su strada solo da sud.', 'In auto da Myre; ultimo tratto su strada stretta, da verificare.', 'Estate', null, null, null, null, null),
  ('NO-4', 'sto', 'it', 'Stø', 'Villaggio di pescatori sulla punta nord dell''isola di Langøya, nelle Vesterålen, affacciato sul Gavlfjorden.', 'In auto da Myre, a fine strada.', 'Estate', null, null, null, null, null),
  ('NO-4', 'bleik', 'it', 'Bleik', 'Villaggio di pescatori sul lato nord-ovest di Andøya, a circa 10 km da Andenes, con una lunga spiaggia di sabbia chiara e l''isolotto di Bleiksøya di fronte.', 'Sulla strada turistica di Andøya, a sud-ovest di Andenes.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-4', 'bleiksoya', 'it', 'Bleiksøya', 'Isolotto disabitato e riserva naturale davanti a Bleik: una piramide ripida con pendii erbosi e scogliere, importante per gli uccelli marini.', 'Si guarda da terra (da Bleik o dall''area di sosta Kleivodden) o in barca; escursioni da verificare.', 'Estate, nella stagione dei nidi', null, null, null, null, null),
  ('NO-4', 'andenes-fyr', 'it', 'Faro di Andenes', 'Faro costiero del 1859 nel villaggio di Andenes, all''estremità nord di Andøya; è un edificio protetto dal 1999.', 'Ad Andenes, vicino al porto.', 'Visite all''interno da verificare', null, null, null, null, null),
  ('NO-4', 'spaceship-aurora', 'it', 'Andøya Space (centro spaziale)', 'Base di lancio per razzi sull''isola di Andøya, attiva dal 1962: da qui sono partiti oltre 1.200 razzi sonda. Accanto c''è un centro per i visitatori.', 'Sulla strada tra Andenes e Bleik.', 'Apertura del centro visitatori da verificare', null, null, null, null, null),
  ('NO-4', 'moysalen', 'it', 'Parco nazionale Møysalen', 'Parco nazionale sull''isola di Hinnøya, nato nel 2003 per proteggere un paesaggio alpino costiero intatto, con cime che escono dal mare e dai fiordi. Il punto più alto è il Møysalen, 1.262 m.', 'Accessi a piedi o in barca; punti di partenza da verificare sul sito dei parchi nazionali.', 'Estate', 'Terreno di alta montagna: con i bambini solo brevi passeggiate ai margini.', null, null, null, null),
  ('NO-4', 'harstad', 'it', 'Harstad', 'Seconda città del Troms per abitanti, in gran parte sull''isola di Hinnøya. Sulla penisola di Trondenes ci sono la chiesa medievale e il centro storico.', 'In auto dalla E10; aeroporto di Harstad/Narvik (Evenes); è uno scalo della rotta costiera.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-4', 'trondenes-kirke', 'it', 'Chiesa di Trondenes', 'La chiesa medievale in pietra più a nord della Norvegia, al margine nord di Harstad.', 'A Trondenes, pochi chilometri a nord del centro di Harstad.', 'Apertura per le visite da verificare', null, null, null, null, null),
  ('NO-4', 'trondenes-senter', 'it', 'Centro storico di Trondenes', 'Museo a Trondenes (Harstad) che racconta oltre 2.000 anni di storia della zona, che in età vichinga fu un centro di potere.', 'A Trondenes, accanto alla chiesa medievale.', 'Orari e giorni di apertura da verificare', null, null, null, null, null),
  ('NO-4', 'narvik', 'it', 'Narvik', 'Città sull''Ofotfjorden, su una penisola tra due fiordi; è il porto della ferrovia del minerale che arriva dalla Svezia.', 'Sulla E6; treni dalla Svezia (linea di Ofoten); aeroporto di Harstad/Narvik (Evenes).', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-4', 'narvik-krigsmuseum', 'it', 'Museo della guerra di Narvik', 'Museo di storia militare nel centro di Narvik, con circa 2.500 m² di esposizione sulla battaglia di Narvik del 1940 e sul nord della Norvegia durante la seconda guerra mondiale.', 'A Narvik, in centro.', 'Orari e giorni di apertura da verificare', 'Temi di guerra: da valutare per i bambini.', null, null, null, null),
  ('NO-4', 'ofotbanen', 'it', 'Ferrovia di Ofoten', 'Linea ferroviaria di 43 km dal porto di Narvik al confine svedese di Riksgränsen, dove prosegue come linea del minerale verso Kiruna e Luleå. Sale dal fiordo alla montagna.', 'Treni dalla stazione di Narvik; orari e biglietti da verificare.', 'Tutto l''anno', null, null, null, null, null),
  ('NO-4', 'gryllefjord', 'it', 'Gryllefjord', 'Villaggio di pescatori sulla costa ovest di Senja, lungo il fiordo omonimo. Qui arriva il traghetto estivo da Andenes e comincia la strada turistica di Senja.', 'Traghetto estivo da Andenes (vedi Trasporti via mare) oppure strada 86 da Finnsnes.', 'Estate (il traghetto per Andenes è stagionale)', null, null, null, null, null),
  ('NO-4', 'torsken', 'it', 'Torsken', 'Villaggio sulla costa ovest di Senja, con una chiesa in legno.', 'Deviazione dalla strada 86 vicino a Gryllefjord.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-4', 'hamn-i-senja', 'it', 'Hamn i Senja', 'Antico emporio e oggi meta turistica sulla costa di Senja, affacciato sul mare aperto davanti alle isolette del Bergsfjorden.', 'Sulla strada 86, lungo la strada turistica di Senja.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-4', 'skaland', 'it', 'Skaland', 'Villaggio sulla riva del Bergsfjorden, sul lato nord-ovest di Senja, con negozio e scuola; era il capoluogo dell''ex comune di Berg.', 'Lungo la strada turistica di Senja.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-4', 'tungeneset', 'it', 'Tungeneset', 'Area di sosta sulla punta tra l''Ersfjorden e lo Steinfjorden: una passerella in larice porta sulle rocce, con la vista sul mare aperto e sulle cime dell''Okshornan.', 'Sulla strada turistica di Senja (strada 862), tra Ersfjord e Skaland.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-4', 'okshornan', 'it', 'Okshornan', 'Fila di cime aguzze sull''Ersfjorden, a Senja; la più alta è lo Store Okshornet, 559 m. Si vedono bene dalla strada turistica, soprattutto da Tungeneset.', 'Si guardano dall''area di sosta Tungeneset, sulla strada turistica di Senja.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-4', 'ersfjord-senja', 'it', 'Ersfjord (Senja)', 'Borgo in fondo all''Ersfjorden, a Senja, sotto le cime dell''Okshornan, con una spiaggia di sabbia bianca e fine.', 'Sulla strada turistica di Senja (strada 862).', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-4', 'bergsbotn', 'it', 'Bergsbotn', 'Braccio di fiordo e borgo a Senja, circa 5 km a est di Skaland. Sulla strada turistica una piattaforma lunga 44 m dà la vista sul Bergsfjorden e sulle cime intorno.', 'Sulla strada turistica di Senja (strada 862).', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-4', 'mefjordvaer', 'it', 'Mefjordvær', 'Villaggio di pescatori sulla costa nord-ovest di Senja, lungo il Mefjorden, circa 3,5 km oltre Senjahopen, a fine strada.', 'Deviazione dalla strada turistica di Senja (strada 7868).', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-4', 'senjahopen', 'it', 'Senjahopen', 'Villaggio lungo il Mefjorden, nella parte nord-ovest di Senja: è uno dei più importanti villaggi di pescatori dell''isola.', 'Sulla deviazione per Mefjordvær dalla strada turistica di Senja.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-4', 'segla', 'it', 'Segla', 'Monte a forma di vela sopra il villaggio di Fjordgård, a Senja, con una parete che cade a picco sul fiordo.', 'A piedi su sentiero da Fjordgård; dislivello, tempi e punto di partenza da verificare.', 'Estate', 'Salita ripida con una cresta esposta in cima: non adatta a bambini piccoli. Il monte si guarda bene anche da Fjordgård.', null, null, null, null),
  ('NO-4', 'fjordgard', 'it', 'Fjordgård', 'Villaggio nella parte nord di Senja, ai piedi del monte Segla, a circa 4 km da Husøy in linea d''aria.', 'Deviazione dalla strada turistica di Senja, con gallerie.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-4', 'husoy', 'it', 'Husøy', 'Villaggio di pescatori che occupa tutta l''isoletta di Husøy, nell''Øyfjorden, davanti alla costa nord-ovest di Senja.', 'Deviazione dalla strada turistica di Senja (strada 7886); l''isola è collegata da una strada su un molo.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-4', 'botnhamn', 'it', 'Botnhamn', 'Piccolo villaggio nella parte nord di Senja, sulla riva ovest del fiordo di Stønnesbotn. Da qui parte il traghetto per Brensholmen, verso Tromsø, e comincia la strada turistica di Senja.', 'Traghetto da Brensholmen (vedi Trasporti via mare) oppure in auto da Finnsnes.', 'Estate (traghetto stagionale: da verificare)', null, null, null, null, null),
  ('NO-4', 'finnsnes', 'it', 'Finnsnes', 'Cittadina sulla terraferma e capoluogo del comune di Senja, proprio di fronte all''isola: il ponte sul Gisundet la collega a Senja. Negozi e servizi.', 'Dalla E6 a Bardufoss; battello veloce da Tromsø e da Harstad, e scalo della rotta costiera (da verificare).', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-4', 'anderdalen', 'it', 'Parco nazionale Ånderdalen', 'Parco nazionale di 134 km² nel sud di Senja, istituito nel 1970 e ampliato nel 2004: foresta costiera di pini e betulle, paludi e laghi, con sentieri segnati.', 'In auto dal lato sud di Senja; ingressi e parcheggi da verificare.', 'Estate', null, null, null, null, null),
  ('NO-4', 'brensholmen', 'it', 'Brensholmen', 'Borgo di pescatori e contadini all''estremità sud-ovest di Kvaløya, nel comune di Tromsø. Da qui parte il traghetto per Botnhamn, a Senja.', 'In auto da Tromsø attraverso Kvaløya; traghetto da Botnhamn (vedi Trasporti via mare).', 'Estate (traghetto stagionale: da verificare)', null, null, null, null, null),
  ('NO-4', 'sommaroy', 'it', 'Sommarøy', 'Antico villaggio di pescatori su un gruppo di isolette a circa 36 km a ovest di Tromsø, molto visitato per le spiagge di sabbia bianca e il paesaggio.', 'In auto da Tromsø attraverso Kvaløya; un ponte collega le isole. Vicino a Brensholmen.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-4', 'kvaloya', 'it', 'Kvaløya', 'L''«isola delle balene», di fronte a Tromsø: con 737 km² è la quinta isola della Norvegia continentale. Fiordi, monti e piccoli borghi; un ponte la collega a Tromsø.', 'In auto da Tromsø dal ponte di Sandnessund.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-4', 'ersfjordbotn', 'it', 'Ersfjordbotn', 'Villaggio su un istmo tra l''Ersfjorden e il Kaldfjorden, sull''isola di Kvaløya, a circa 15 km da Tromsø, in fondo a un fiordo chiuso da cime ripide.', 'In auto da Tromsø attraverso Kvaløya.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-4', 'ishavskatedralen', 'it', 'Cattedrale dell''Artico', 'Chiesa moderna di Tromsdalen, sul lato est di Tromsø oltre il ponte, con la grande facciata a triangoli bianchi; è una chiesa parrocchiale, non una cattedrale.', 'A Tromsdalen: a piedi o in autobus dal centro di Tromsø, oltre il ponte.', 'Tutto l''anno; orari di visita e concerti da verificare', null, null, null, null, null),
  ('NO-4', 'fjellheisen', 'it', 'Funivia Fjellheisen', 'Funivia di Tromsø: dalla stazione a valle di Tromsdalen sale in circa quattro minuti a Storsteinen, una terrazza a circa 420 m con la vista sulla città e sui fiordi.', 'Stazione a valle a Tromsdalen, oltre il ponte dal centro di Tromsø.', 'Tutto l''anno; orari, biglietti e chiusure per vento da verificare', null, null, null, null, null),
  ('NO-4', 'polarmuseet', 'it', 'Museo polare', 'Museo di Tromsø sulla caccia artica norvegese, sulla scienza e sulle spedizioni polari, aperto nel 1978 in uno degli edifici più antichi della città.', 'A Tromsø, in centro, sul porto.', 'Orari e giorni di apertura da verificare', null, null, null, null, null),
  ('NO-4', 'tromso-museum', 'it', 'Museo universitario di Tromsø', 'Museo dell''università di Tromsø, fondato nel 1872: è una delle più antiche istituzioni scientifiche del nord della Norvegia, con sezioni su natura e culture del nord.', 'Nella parte sud dell''isola di Tromsøya; in autobus o in auto dal centro.', 'Orari e giorni di apertura da verificare', null, null, null, null, null),
  ('NO-4', 'botanisk-hage', 'it', 'Giardino botanico artico-alpino', 'Il giardino botanico più a nord del mondo, aperto nel 1994 e curato dal museo universitario di Tromsø: piante artiche e alpine di tutto l''emisfero nord.', 'Accanto al campus dell''università, nella parte nord dell''isola di Tromsøya.', 'Estate (stagione delle fioriture)', null, null, null, null, null),
  ('NO-4', 'tromso-domkirke', 'it', 'Cattedrale di Tromsø', 'Cattedrale luterana nel centro di Tromsø, sede della diocesi del Nord-Hålogaland; è un edificio in legno.', 'A Tromsø, in centro.', 'Apertura per le visite da verificare', null, null, null, null, null),
  ('NO-4', 'vitensenter', 'it', 'Centro della scienza del Nord', 'Centro di scienza per il pubblico nel campus dell''università di Tromsø, con esperimenti da provare; accanto c''è il planetario.', 'Nel campus dell''università, nella parte nord dell''isola di Tromsøya.', 'Orari e giorni di apertura da verificare', null, null, null, null, null),
  ('NO-4', 'lyngsalpene', 'it', 'Alpi di Lyngen', 'Catena di montagne sulla penisola di Lyngen, a est di Tromsø, con cime e ghiacciai sopra i fiordi.', 'In auto da Tromsø; ci sono traghetti sui fiordi lungo il percorso (vedi Trasporti via mare), da verificare.', 'Estate', null, null, null, null, null),
  ('NO-4', 'lyngseidet', 'it', 'Lyngseidet', 'Capoluogo del comune di Lyngen, su un istmo largo circa 3 km tra un braccio dell''Ullsfjorden e il Lyngenfjorden, ai piedi delle Alpi di Lyngen. Negozi e servizi.', 'In auto da Tromsø, con traghetto sull''Ullsfjorden (da verificare) oppure per la E8 e la E6.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-4', 'malselvfossen', 'it', 'Cascata Målselvfossen', 'Cascata sul fiume Målselva, nel comune di Målselv, nell''entroterra del Troms.', 'In auto, con una deviazione dalla E6 nella zona di Bardufoss.', 'Estate', null, null, null, null, null),
  ('NO-4', 'vikingtidsmuseet', 'it', 'Museo dell''età vichinga (navi vichinghe)', 'Il museo delle navi vichinghe di Bygdøy, con le navi funerarie di Oseberg, Gokstad e Tune. È chiuso dal 2021 per l''ampliamento che lo trasforma nel Museo dell''età vichinga; la riapertura è annunciata per il 2027.', 'Sulla penisola di Bygdøy, a ovest del centro di Oslo: autobus oppure, in estate, battello dal molo del municipio.', 'Chiuso per lavori: data di riapertura da verificare sul sito prima di metterlo in programma', 'Riapertura annunciata per il 2027: ad agosto 2027 potrebbe essere aperto oppure no. Da verificare.', null, null, null, null),
  ('NO-4', 'nasjonalmuseet', 'it', 'Museo nazionale', 'Il più grande museo d''arte dei paesi nordici, aperto nella nuova sede nel 2022: arte, architettura e design, con una sala dedicata a Munch e una versione dell''Urlo.', 'In centro a Oslo, accanto ad Aker Brygge e al municipio.', 'Tutto l''anno; giorni e orari di apertura da verificare sul sito', null, null, null, null, null),
  ('NO-4', 'naturhistorisk-museum', 'it', 'Museo di storia naturale', 'Il più antico e più grande museo di storia naturale della Norvegia, dell''Università di Oslo: zoologia, geologia, fossili e dinosauri, dentro il giardino botanico di Tøyen.', 'Nel quartiere di Tøyen, a est del centro di Oslo; metropolitana fino a Tøyen.', 'Tutto l''anno; giorni e orari di apertura da verificare sul sito', null, null, null, null, null),
  ('NO-4', 'botanisk-hage-oslo', 'it', 'Giardino botanico di Oslo', 'Il più antico giardino botanico della Norvegia, fondato nel 1814 e curato dall''Università di Oslo: prati, serre e collezioni all''aperto intorno al museo di storia naturale.', 'Nel quartiere di Tøyen, a est del centro di Oslo.', 'Tutto l''anno; orari dei cancelli e delle serre da verificare', null, null, null, null, null),
  ('NO-4', 'akershus', 'it', 'Fortezza di Akershus', 'Castello medievale e fortezza sul fiordo, costruita per difendere Oslo. Si passeggia liberamente tra bastioni e cortili, con vista sul porto; all''interno ci sono il castello e alcuni musei.', 'In centro a Oslo, sul lungomare, a pochi minuti a piedi dal municipio.', 'Area della fortezza aperta tutto l''anno; castello e musei con orari da verificare', null, null, null, null, null),
  ('NO-4', 'operahuset', 'it', 'Teatro dell''Opera di Oslo', 'Sede dell''Opera e del Balletto nazionali, nel quartiere di Bjørvika in fondo al fiordo di Oslo. Il tetto in marmo bianco scende fino all''acqua e ci si cammina sopra.', 'In centro a Oslo, accanto alla stazione centrale.', 'Il tetto è accessibile tutto l''anno; con ghiaccio o pioggia il marmo è scivoloso', null, null, null, null, null),
  ('NO-4', 'radhuset-oslo', 'it', 'Municipio di Oslo', 'Il municipio in mattoni con le due torri, sul porto: nelle sue sale decorate da grandi affreschi si consegna ogni anno il premio Nobel per la pace.', 'In centro a Oslo, sul lungomare.', 'Apertura al pubblico da verificare: chiude in occasione di eventi', null, null, null, null, null),
  ('NO-4', 'nobels-fredssenter', 'it', 'Centro Nobel per la pace', 'Museo dedicato al premio Nobel per la pace e ai suoi vincitori, con mostre multimediali, nell''ex stazione ferroviaria Vestbanen.', 'In centro a Oslo, tra il municipio e Aker Brygge.', 'Tutto l''anno; giorni e orari di apertura da verificare sul sito', null, null, null, null, null),
  ('NO-4', 'slottet', 'it', 'Palazzo reale di Oslo', 'Residenza ufficiale del re di Norvegia, costruita nella prima metà dell''Ottocento in cima al viale Karl Johans gate. Il parco intorno è aperto a tutti; davanti al palazzo si vede il cambio della guardia.', 'In centro a Oslo, in fondo a Karl Johans gate.', 'Parco tutto l''anno; visite guidate all''interno solo in estate, da verificare', null, null, null, null, null),
  ('NO-4', 'astrup-fearnley', 'it', 'Museo Astrup Fearnley', 'Museo privato di arte contemporanea, in un edificio in legno e vetro di Renzo Piano sulla punta di Tjuvholmen, con un piccolo parco di sculture e una spiaggetta accanto.', 'A Tjuvholmen, in fondo ad Aker Brygge, a piedi dal centro di Oslo.', 'Tutto l''anno; giorni e orari di apertura da verificare sul sito', null, null, null, null, null),
  ('NO-4', 'maritimt-museum', 'it', 'Museo marittimo norvegese', 'Museo della navigazione norvegese, dalle barche tradizionali alle navi moderne, sulla penisola di Bygdøy accanto ai musei Fram e Kon-Tiki.', 'A Bygdøynes, sulla penisola di Bygdøy: autobus oppure, in estate, battello dal molo del municipio.', 'Tutto l''anno; giorni e orari di apertura da verificare sul sito', null, null, null, null, null),
  ('NO-4', 'ekebergparken', 'it', 'Parco delle sculture di Ekeberg', 'Parco di sculture nel bosco sulla collina di Ekeberg, a sud-est del centro, con opere di artisti internazionali lungo i sentieri e una vista ampia sulla città e sul fiordo.', 'In tram dal centro di Oslo fino alla fermata Ekebergparken.', 'Tutto l''anno', null, null, null, null, null),
  ('NO-4', 'oscarsborg', 'it', 'Fortezza di Oscarsborg', 'Fortezza costiera su due isolotti nel punto più stretto del fiordo di Oslo, davanti a Drøbak. Il 9 aprile 1940 da qui fu affondato l''incrociatore tedesco Blücher.', 'In battello da Drøbak, circa 40 km a sud di Oslo; orari del battello da verificare.', 'Soprattutto in estate; battello e musei da verificare', null, null, null, null, null),
  ('NO-4', 'blaafarvevaerket', 'it', 'Blaafarveværket', 'L''antica fabbrica del blu cobalto di Modum, attiva dal 1776 al 1898 e nell''Ottocento la maggiore impresa mineraria del paese. Oggi è un museo all''aperto con mostre d''arte, edifici storici e le miniere di cobalto poco lontano.', 'Ad Åmot, nel comune di Modum, a ovest di Oslo.', 'Apertura stagionale: giorni e orari da verificare sul sito', null, null, null, null, null),
  ('NO-4', 'kistefos', 'it', 'Museo Kistefos', 'Parco di sculture e museo d''arte intorno a un''antica cartiera sul fiume Randselva, a Jevnaker. L''edificio più noto è «The Twist», una galleria che attraversa il fiume come un ponte attorcigliato.', 'A Jevnaker, a nord di Oslo.', 'Apertura stagionale: giorni e orari da verificare sul sito', null, null, null, null, null),
  ('NO-4', 'bergverksmuseum', 'it', 'Museo minerario norvegese e miniere d''argento', 'Museo di Kongsberg sulla storia delle miniere d''argento, attive per oltre tre secoli. Poco fuori città si entra nella miniera con un trenino che percorre una galleria per oltre due chilometri.', 'Il museo è nel centro di Kongsberg; l''ingresso della miniera (Saggrenda) è a qualche chilometro.', 'Museo tutto l''anno, trenino della miniera stagionale: date e orari da verificare', 'In miniera la temperatura è bassa tutto l''anno: servono vestiti caldi.', null, null, null, null),
  ('NO-4', 'fredrikstad-gamleby', 'it', 'Città vecchia di Fredrikstad', 'La città fortificata meglio conservata del nord Europa: bastioni, fossati e strade acciottolate del Seicento, sulla riva est del fiume Glomma.', 'A Fredrikstad; dal centro moderno si attraversa il fiume con un piccolo traghetto cittadino.', 'Tutto l''anno', null, null, null, null, null),
  ('NO-4', 'fredriksten', 'it', 'Fortezza di Fredriksten', 'Grande fortezza sopra la città di Halden, al confine con la Svezia: qui nel 1718 morì il re svedese Carlo XII durante l''assedio. Mura, bastioni e musei, con vista sulla città e sul fiordo.', 'A Halden, a piedi dal centro oppure in auto fino ai parcheggi della fortezza.', 'Area aperta tutto l''anno; musei e visite guidate soprattutto in estate, da verificare', null, null, null, null, null),
  ('NO-4', 'eidsvollsbygningen', 'it', 'Eidsvollsbygningen', 'La villa dove il 17 maggio 1814 fu firmata la Costituzione norvegese. Oggi è un museo nazionale, con le sale arredate come allora.', 'A Eidsvoll Verk, a nord dell''aeroporto di Gardermoen.', 'Tutto l''anno; giorni e orari di apertura da verificare sul sito', null, null, null, null, null),
  ('NO-4', 'midgard', 'it', 'Tumuli di Borre e centro vichingo Midgard', 'Il parco di Borre ha la più grande raccolta di tumuli funerari monumentali del nord Europa, di età vichinga e precedente. Accanto ci sono il centro Midgard, con le mostre, e la ricostruzione di una grande sala vichinga.', 'A Borre, tra Horten e Åsgårdstrand, sulla costa ovest del fiordo di Oslo.', 'Parco tutto l''anno; centro e sala vichinga con orari da verificare', null, null, null, null, null),
  ('NO-4', 'hvalfangstmuseet', 'it', 'Museo della caccia alla balena', 'Museo di Sandefjord dedicato alle balene e alla caccia alla balena, di cui la città fu un centro mondiale; è l''unico museo specializzato sull''argomento in Europa.', 'Nel centro di Sandefjord.', 'Tutto l''anno; giorni e orari di apertura da verificare sul sito', null, null, null, null, null),
  ('NO-4', 'verdens-ende', 'it', 'Verdens Ende', '«La fine del mondo»: la punta sud dell''isola di Tjøme, fatta di scogli lisci e isolotti affacciati sullo Skagerrak, con la copia di un antico faro a bilanciere. È una delle porte del parco nazionale di Færder.', 'In auto da Tønsberg attraverso le isole di Nøtterøy e Tjøme, fino in fondo alla strada.', 'Tutto l''anno', null, null, null, null, null),
  ('NO-4', 'faerder', 'it', 'Parco nazionale di Færder', 'Parco nazionale quasi tutto marino, nel fiordo di Oslo esterno: isole, scogli e fondali davanti a Nøtterøy e Tjøme. Il centro visitatori è a Verdens Ende.', 'Dalla terraferma si vede da Verdens Ende; le isole si raggiungono solo in barca.', 'Estate', null, null, null, null, null),
  ('NO-4', 'heddal-stavkirke', 'it', 'Stavkirke di Heddal', 'La più grande chiesa in legno a pali portanti (stavkirke) della Norvegia, del Duecento, con tre torrette e tetti a più livelli. È ancora la chiesa parrocchiale del paese.', 'A Heddal, lungo la E134 a ovest di Notodden.', 'Visite soprattutto in estate: giorni e orari da verificare', null, null, null, null, null),
  ('NO-4', 'vemork', 'it', 'Vemork e il museo dei lavoratori dell''industria', 'Centrale idroelettrica del 1911 sopra Rjukan, oggi museo: racconta la nascita dell''industria norvegese e il sabotaggio dell''acqua pesante del 1943. Rjukan e Notodden sono patrimonio UNESCO.', 'A ovest di Rjukan; dal parcheggio si attraversa un ponte sospeso sulla gola e si sale a piedi (navetta da verificare).', 'Tutto l''anno; giorni e orari di apertura da verificare sul sito', null, null, null, null, null),
  ('NO-4', 'gaustatoppen', 'it', 'Gaustatoppen', 'La montagna più alta del Telemark (1.883 m), sopra Rjukan: nelle giornate limpide si vede una parte molto ampia della Norvegia meridionale. Dentro la montagna sale una funicolare, la Gaustabanen.', 'A piedi su sentiero sassoso dal parcheggio di Stavsro, oppure con la funicolare interna; strada di accesso di montagna.', 'Estate; funicolare con date e orari da verificare', 'Il sentiero è su pietraia, senza tratti esposti: fattibile con bambini abituati a camminare, da valutare con quello di 5 anni. In cima fa freddo anche in agosto.', null, null, null, null),
  ('NO-4', 'bo-sommarland', 'it', 'Bø Sommarland', 'Grande parco acquatico all''aperto a Bø, nel Telemark, con scivoli, piscine con le onde e aree per i più piccoli.', 'A Bø, nel Telemark, circa due ore di strada da Oslo.', 'Solo in estate: date di apertura da verificare (di solito chiude a metà agosto)', 'La stagione finisce presto: verificare le date di chiusura per l''agosto del viaggio.', null, null, null, null),
  ('NO-4', 'telemarkskanalen', 'it', 'Canale del Telemark', 'Via d''acqua di circa 105 km tra Skien e Dalen, che collega laghi lunghi e stretti con 18 chiuse scavate nell''Ottocento. Si percorre su battelli storici oppure si guardano le chiuse da terra, per esempio a Vrangfoss e a Ulefoss.', 'Le chiuse di Ulefoss, Vrangfoss e Lunde si raggiungono in auto; i battelli partono da Skien, Lunde e Dalen.', 'Battelli solo in estate: date, orari e tratte da verificare', null, null, null, null, null),
  ('NO-4', 'maihaugen', 'it', 'Maihaugen', 'Museo all''aperto di Lillehammer, tra i più grandi del nord Europa: circa 200 edifici, dalle fattorie della valle del Gudbrandsdal con una stavkirke fino a un quartiere di case del Novecento.', 'A Lillehammer, a piedi dal centro (in salita) o in auto.', 'Tutto l''anno; in estate più edifici aperti e figuranti: orari da verificare', null, null, null, null, null),
  ('NO-4', 'lysgardsbakkene', 'it', 'Trampolini di Lysgårdsbakkene', 'I due trampolini per il salto con gli sci delle Olimpiadi invernali del 1994, sopra Lillehammer. Dall''alto si vedono la città e il lago Mjøsa.', 'Sopra Lillehammer: si sale lungo la scalinata accanto al trampolino o, in estate, con la seggiovia (da verificare).', 'Tutto l''anno; seggiovia solo in stagione', null, null, null, null, null),
  ('NO-4', 'lilleputthammer', 'it', 'Lilleputthammer', 'Parco per famiglie a Øyer, pensato per i bambini più piccoli: al centro c''è la via principale di Lillehammer com''era negli anni Trenta, ricostruita in miniatura, con giostre tranquille intorno.', 'A Øyer, lungo la E6, circa 20 km a nord di Lillehammer.', 'Solo in estate: date di apertura da verificare', null, null, null, null, null),
  ('NO-4', 'vegmuseum', 'it', 'Museo norvegese della strada', 'Museo tecnico sulla storia delle strade e dei veicoli in Norvegia, accanto al parco di Hunderfossen: mostre al coperto, un grande parco con macchine e ponti storici e una galleria nella roccia di oltre 200 metri.', 'A Hunderfossen, lungo la E6 a nord di Lillehammer.', 'Tutto l''anno; giorni e orari di apertura da verificare sul sito', null, null, null, null, null),
  ('NO-4', 'skogmuseum', 'it', 'Museo norvegese della foresta', 'Museo nazionale di Elverum dedicato a bosco, caccia e pesca: mostre di natura e di storia, un acquario con i pesci d''acqua dolce e un''area all''aperto sul fiume Glomma.', 'A Elverum, lungo il fiume Glomma.', 'Tutto l''anno; giorni e orari di apertura da verificare sul sito', null, null, null, null, null),
  ('NO-4', 'jernbanemuseum', 'it', 'Museo ferroviario norvegese', 'Il museo ferroviario nazionale, a Hamar sulla riva del lago Mjøsa, tra i più antichi del mondo: locomotive e carrozze storiche, vecchie stazioni nel parco e, in estate, un trenino.', 'A Hamar, a nord del centro, sul lago.', 'Tutto l''anno; giorni e orari di apertura da verificare sul sito', null, null, null, null, null),
  ('NO-4', 'domkirkeodden', 'it', 'Domkirkeodden e le rovine della cattedrale di Hamar', 'Museo su una penisola del lago Mjøsa: le rovine della cattedrale medievale di Hamar, protette da una grande teca di vetro, un museo all''aperto con edifici rurali e un orto di erbe.', 'A Hamar, sul lago, a ovest del centro.', 'Apertura stagionale: giorni e orari da verificare sul sito', null, null, null, null, null),
  ('NO-4', 'ringebu-stavkirke', 'it', 'Stavkirke di Ringebu', 'Una delle più grandi stavkirke rimaste, costruita intorno al 1220 nella valle del Gudbrandsdal; la torre rossa fu aggiunta nel Seicento.', 'Poco fuori dalla E6 a Ringebu, a nord di Lillehammer.', 'Visite soprattutto in estate: giorni e orari da verificare', null, null, null, null, null),
  ('NO-4', 'lom-stavkirke', 'it', 'Stavkirke di Lom', 'Stavkirke del XII secolo, ampliata nel Seicento e tra le più grandi della Norvegia; è ancora la chiesa del paese, al centro di Lom.', 'Nel centro di Lom (Fossbergom), all''incrocio tra la strada 15 e la strada 55 del Sognefjell.', 'Visite soprattutto in estate: giorni e orari da verificare', null, null, null, null, null),
  ('NO-4', 'rondane', 'it', 'Parco nazionale di Rondane', 'Il più antico parco nazionale della Norvegia, istituito nel 1962: un massiccio di cime arrotondate, dieci delle quali oltre i 2.000 metri, con altopiani di licheni dove vivono le renne selvatiche.', 'Dagli accessi di Mysusæter (sopra Otta) e Høvringen, oppure lungo la strada turistica di Rondane sul lato est.', 'Estate e inizio autunno; in quota la neve può restare fino a luglio', 'Dai parcheggi partono sentieri pianeggianti adatti anche ai bambini; le cime sono escursioni lunghe.', null, null, null, null),
  ('NO-4', 'snohetta-viewpoint', 'it', 'Belvedere di Snøhetta', 'Padiglione in legno e vetro disegnato dallo studio Snøhetta e aperto nel 2011 sul Tverrfjellet, nel Dovrefjell: dalla vetrata si guarda il monte Snøhetta e, con fortuna, renne selvatiche e buoi muschiati.', 'Da Hjerkinn, sulla E6: dal parcheggio un sentiero facile di circa 1,5 km.', 'Solo in estate e inizio autunno: date di apertura da verificare', null, null, null, null, null),
  ('NO-4', 'galdhopiggen', 'it', 'Galdhøpiggen', 'Con 2.469 metri è la montagna più alta della Norvegia e del nord Europa, nel Jotunheimen.', 'Da Juvasshytta, con guida, attraversando in cordata un ghiacciaio; oppure da Spiterstulen, senza ghiacciaio ma con molto più dislivello.', 'Estate', 'Escursione d''alta montagna, lunga: non adatta a bambini di 5 e 8 anni. La strada per Juvasshytta arriva comunque a oltre 1.800 m, con vista sulle cime.', null, null, null, null),
  ('NO-4', 'besseggen', 'it', 'Besseggen', 'La cresta più famosa del Jotunheimen, tra il lago verde Gjende e il lago blu Bessvatnet, più alto di quasi 400 metri. È una delle escursioni più percorse della Norvegia.', 'Da Gjendesheim: di solito si prende il battello fino a Memurubu e si torna a piedi lungo la cresta.', 'Estate; battello sul Gjende con orari da verificare', 'Lunga, con un tratto ripido ed esposto dove ci si aiuta con le mani: non adatta a bambini piccoli. Il solo battello sul Gjende è una bella alternativa.', null, null, null, null),
  ('NO-4', 'sognefjellsvegen', 'it', 'Strada del Sognefjell', 'Strada turistica nazionale tra Lom e il Lustrafjord (strada 55): è il valico stradale più alto del nord Europa, a 1.434 metri, tra i ghiacciai e le cime del Jotunheimen.', 'Strada 55 tra Lom e Gaupne.', 'Chiusa in inverno, di solito da novembre a maggio: aperture da verificare', 'Anche in agosto in quota può esserci neve ai lati della strada e fare freddo.', null, null, null, null),
  ('NO-4', 'valdresflye', 'it', 'Valdresflye', 'Altopiano a quasi 1.400 metri al margine est del Jotunheimen, attraversato da una strada turistica nazionale (strada 51) che porta verso il lago Gjende.', 'Strada 51 tra Fagernes e Vågå.', 'Chiusa in inverno: aperture da verificare', null, null, null, null, null),
  ('NO-4', 'femundsmarka', 'it', 'Parco nazionale di Femundsmarka', 'Parco nazionale al confine con la Svezia, tra Røros ed Engerdal: laghi, torrenti e radi boschi di pini, molto amato per la canoa e la pesca. Sul grande lago Femunden naviga in estate un battello storico.', 'Dai punti di accesso sul lago Femunden (per esempio Elgå o, dal lato di Røros, Synnervika con il battello).', 'Estate e inizio autunno; in quota la neve può restare fino a luglio', null, null, null, null, null),
  ('NO-4', 'bryggen', 'it', 'Bryggen', 'Il vecchio molo dei mercanti anseatici a Bergen, patrimonio UNESCO: file di case in legno colorate, ricostruite dopo l''incendio del 1702, con vicoli stretti, botteghe e laboratori.', 'Nel centro di Bergen, sul lato est del porto.', 'Tutto l''anno', null, null, null, null, null),
  ('NO-4', 'hanseatiske-museum', 'it', 'Museo anseatico e Schøtstuene', 'Museo sulla vita dei mercanti tedeschi della Lega anseatica a Bryggen, con le sale comuni (Schøtstuene) dove mangiavano e si riunivano. L''edificio principale è in restauro da anni.', 'A Bryggen, nel centro di Bergen.', 'Verificare sul sito quali edifici sono visitabili', null, null, null, null, null),
  ('NO-4', 'bergenhus', 'it', 'Fortezza di Bergenhus', 'Una delle fortezze in pietra più antiche e meglio conservate della Norvegia, all''ingresso del porto di Bergen: comprende la sala reale di Håkon, del Duecento, e la torre Rosenkrantz.', 'Nel centro di Bergen, in fondo a Bryggen.', 'Area aperta tutto l''anno; sala e torre con orari da verificare', null, null, null, null, null),
  ('NO-4', 'floibanen', 'it', 'Funicolare Fløibanen e monte Fløyen', 'Funicolare che dal centro di Bergen sale in pochi minuti sul Fløyen, a circa 320 metri: vista sulla città, un grande parco giochi, il «bosco dei troll» e sentieri facili.', 'La stazione a valle è nel centro di Bergen, a due passi da Bryggen.', 'Tutto l''anno; in estate conviene verificare attese e orari', null, null, null, null, null),
  ('NO-4', 'ulriken', 'it', 'Ulriken e funivia Ulriksbanen', 'La più alta delle sette montagne che circondano Bergen (643 m). In cima si arriva con la funivia Ulriksbanen: vista sulla città, sul mare e sulle isole.', 'La stazione a valle della funivia è a qualche chilometro dal centro (autobus).', 'Tutto l''anno; la funivia si ferma con vento forte', null, null, null, null, null),
  ('NO-4', 'vilvite', 'it', 'VilVite, centro della scienza di Bergen', 'Centro della scienza con esperimenti da toccare e provare su tecnologia, energia, corpo e mare: pensato per bambini e ragazzi.', 'A Bergen, nel quartiere di Marineholmen, a sud del centro.', 'Tutto l''anno; giorni e orari di apertura da verificare sul sito', null, null, null, null, null),
  ('NO-4', 'kode', 'it', 'KODE, musei d''arte di Bergen', 'Uno dei più grandi musei d''arte dei paesi nordici, in più edifici affacciati sul laghetto Lille Lungegårdsvann: pittura norvegese, con molte opere di Munch, arti decorative e arte contemporanea.', 'Nel centro di Bergen.', 'Tutto l''anno; giorni e orari di apertura da verificare sul sito', null, null, null, null, null),
  ('NO-4', 'fiskerimuseum', 'it', 'Museo norvegese della pesca', 'Museo sulla pesca e sul mare, fondato nel 1880, dentro antichi magazzini in legno sul fiordo, nel quartiere di Sandviken.', 'A Sandviken, a nord del centro di Bergen; in estate anche in battello dal mercato del pesce (da verificare).', 'Tutto l''anno; giorni e orari di apertura da verificare sul sito', null, null, null, null, null),
  ('NO-4', 'troldhaugen', 'it', 'Troldhaugen, casa di Edvard Grieg', 'La villa dove il compositore Edvard Grieg visse dal 1885 al 1907, con il museo, la casetta in riva al lago dove componeva e una sala da concerti.', 'A sud di Bergen, verso l''aeroporto: metropolitana leggera fino a Hop e poi a piedi, oppure in auto.', 'Tutto l''anno; concerti soprattutto in estate, da verificare', null, null, null, null, null),
  ('NO-4', 'fantoft-stavkirke', 'it', 'Stavkirke di Fantoft', 'Stavkirke ricostruita nel bosco alla periferia di Bergen: l''originale, del XII secolo, veniva da Fortun sul Sognefjord e bruciò nel 1992; la copia fedele è del 1997.', 'A Fantoft, a sud di Bergen: metropolitana leggera e pochi minuti a piedi.', 'Visite solo in estate: giorni e orari da verificare', null, null, null, null, null),
  ('NO-4', 'jugendstilsenteret', 'it', 'Centro dell''Art Nouveau di Ålesund', 'Museo nell''antica farmacia del Cigno, nel centro di Ålesund: racconta l''incendio del 1904 e la ricostruzione della città in stile Art Nouveau.', 'Nel centro di Ålesund.', 'Tutto l''anno; giorni e orari di apertura da verificare sul sito', null, null, null, null, null),
  ('NO-4', 'aksla', 'it', 'Belvedere di Aksla (Fjellstua)', 'Il colle sopra Ålesund con la vista più nota della città, delle isole e delle Alpi di Sunnmøre. In cima c''è il caffè Fjellstua, aperto nel 1903.', 'A piedi dal parco cittadino, su una scalinata di poco più di 400 gradini, oppure in auto.', 'Tutto l''anno', null, null, null, null, null),
  ('NO-4', 'sunnmore-museum', 'it', 'Museo di Sunnmøre', 'Museo all''aperto sul fiordo, pochi chilometri a est di Ålesund: decine di vecchie case della regione, una grande raccolta di barche e copie di navi vichinghe.', 'A Borgundgavlen, circa 4 km a est del centro di Ålesund.', 'Apertura stagionale: giorni e orari da verificare sul sito', null, null, null, null, null),
  ('NO-4', 'fjordsenter', 'it', 'Centro norvegese dei fiordi', 'Centro visitatori del patrimonio UNESCO dei fiordi a Geiranger. Accanto parte una passerella con scalinate che scende lungo la cascata del torrente fino al villaggio.', 'A Geiranger, sopra il villaggio, lungo la strada 63.', 'Apertura da verificare; passerella della cascata in estate', null, null, null, null, null),
  ('NO-4', 'flydalsjuvet', 'it', 'Flydalsjuvet', 'Gola e punto panoramico sopra Geiranger: è la veduta classica del villaggio e del Geirangerfjord, con le navi in rada.', 'Area di sosta lungo la strada 63, circa 4 km a sud di Geiranger.', 'Estate; la strada verso sud è chiusa in inverno', 'Tenere i bambini lontani dal bordo: fuori dalle piattaforme recintate le rocce sono esposte.', null, null, null, null),
  ('NO-4', 'loen-skylift', 'it', 'Loen Skylift', 'Funivia aperta nel 2017 che da Loen, sul Nordfjord, sale di oltre 1.000 metri in pochi minuti fino al monte Hoven: è tra le più ripide del mondo. In cima ci sono un ristorante e sentieri.', 'A Loen, sulla strada 60 lungo il Nordfjord.', 'Tutto l''anno; orari da verificare, si ferma con vento forte', null, null, null, null, null),
  ('NO-4', 'lovatnet', 'it', 'Lago Lovatnet', 'Lago glaciale dal colore verde chiaro nella valle di Lodalen, sopra Loen, chiuso tra pareti ripide; in fondo alla valle c''è il ghiacciaio Kjenndalsbreen.', 'Strada stretta da Loen lungo il lago (in parte a pedaggio, da verificare).', 'Estate', null, null, null, null, null),
  ('NO-4', 'gamle-bergen', 'it', 'Museo della vecchia Bergen', 'Museo all''aperto con una cinquantina di case in legno del Settecento e dell''Ottocento, ricostruite come una piccola città; in estate figuranti in costume animano strade e botteghe.', 'A Sandviken, a nord del centro di Bergen (autobus).', 'Apertura stagionale: giorni e orari da verificare sul sito', null, null, null, null, null),
  ('NO-4', 'urnes-stavkirke', 'it', 'Stavkirke di Urnes', 'La più antica stavkirke della Norvegia, del XII secolo, patrimonio UNESCO: è famosa per gli intagli con animali intrecciati sul portale nord. Sta su un poggio sopra il Lustrafjord.', 'A Ornes, sulla riva est del Lustrafjord: piccolo traghetto da Solvorn (orari da verificare) oppure strada stretta lungo il fiordo.', 'Visite solo in estate: giorni e orari da verificare', null, null, null, null, null),
  ('NO-4', 'borgund-stavkirke', 'it', 'Stavkirke di Borgund', 'La stavkirke meglio conservata della Norvegia, costruita intorno al 1180: tetti a più livelli con teste di drago sui colmi. Accanto c''è un centro visitatori.', 'A Borgund, nella valle di Lærdal, poco fuori dalla E16.', 'Visite soprattutto in estate: giorni e orari da verificare', null, null, null, null, null),
  ('NO-4', 'hopperstad-stavkirke', 'it', 'Stavkirke di Hopperstad', 'Stavkirke del XII secolo, tra le più antiche rimaste, a Vik sul Sognefjord; fu restaurata nell''Ottocento prendendo a modello Borgund.', 'A Vikøyri, nel comune di Vik, sulla riva sud del Sognefjord.', 'Visite solo in estate: giorni e orari da verificare', null, null, null, null, null),
  ('NO-4', 'jostedalsbreen', 'it', 'Parco nazionale del Jostedalsbreen', 'Il parco protegge il Jostedalsbreen, il più grande ghiacciaio dell''Europa continentale, e le valli intorno. Le lingue più facili da avvicinare sono Nigardsbreen e Briksdalsbreen, che hanno una scheda a parte.', 'Dai centri visitatori di Jostedal, Fjærland e Oppstryn e dalle valli laterali.', 'Estate e inizio autunno; in quota la neve può restare fino a luglio', 'Sul ghiaccio si va solo con una guida; sotto le fronti dei ghiacciai vanno rispettate le recinzioni.', null, null, null, null),
  ('NO-4', 'gaularfjellet', 'it', 'Strada del Gaularfjell', 'Strada turistica nazionale tra il Sognefjord e il Sunnfjord, poco trafficata: tornanti, cascate e la piattaforma panoramica «Utsikten» sospesa sulla valle.', 'Strada 613 da Balestrand verso nord.', 'Il tratto di valico è chiuso in inverno: aperture da verificare', null, null, null, null, null),
  ('NO-4', 'njardarheimr', 'it', 'Gudvangen e il villaggio vichingo Njardarheimr', 'Villaggio in fondo al Nærøyfjord, dove attraccano i battelli da Flåm. Accanto al molo c''è Njardarheimr, un villaggio vichingo ricostruito con artigiani e figuranti.', 'Sulla E16, tra Flåm e Voss; in battello da Flåm lungo il Nærøyfjord.', 'Villaggio vichingo: apertura e orari da verificare', null, null, null, null, null),
  ('NO-4', 'voss', 'it', 'Voss', 'Cittadina sul lago Vangsvatnet, tra Bergen e i fiordi, nota per gli sport all''aperto. Dalla stazione una cabinovia sale al monte Hanguren.', 'Sulla E16 e sulla ferrovia Oslo–Bergen.', 'Tutto l''anno', null, null, null, null, null),
  ('NO-4', 'tvindefossen', 'it', 'Cascata Tvindefossen', 'Cascata a ventaglio che scende su una parete a gradoni, a pochi passi dalla strada, circa 12 km a nord di Voss.', 'Accanto alla E16, tra Voss e Gudvangen.', 'Tutto l''anno; più acqua in primavera e a inizio estate', null, null, null, null, null),
  ('NO-4', 'hardangervidda-natursenter', 'it', 'Centro natura dell''Hardangervidda', 'Centro visitatori del parco nazionale dell''Hardangervidda, a Øvre Eidfjord: mostre interattive su natura, clima e renne selvatiche e un film panoramico.', 'A Øvre Eidfjord, sulla strada 7, ai piedi della salita verso Vøringsfossen.', 'Apertura stagionale: giorni e orari da verificare sul sito', null, null, null, null, null),
  ('NO-4', 'hardangervidda', 'it', 'Parco nazionale dell''Hardangervidda', 'Il più grande parco nazionale della Norvegia (oltre 3.400 km²), sul più vasto altopiano d''alta quota d''Europa: laghi, torbiere e le più grandi mandrie di renne selvatiche del continente.', 'La strada 7 attraversa l''altopiano tra Eidfjord e Geilo; sentieri dai rifugi lungo la strada.', 'Estate e inizio autunno; in quota la neve può restare fino a luglio', null, null, null, null, null),
  ('NO-4', 'folgefonna', 'it', 'Parco nazionale del Folgefonna', 'Parco nazionale sulla penisola tra l''Hardangerfjord e i suoi rami, intorno al ghiacciaio Folgefonna, il terzo della Norvegia per estensione.', 'Dalle valli intorno alla penisola: per esempio Sunndal (lago Bondhusvatnet), Odda e Rosendal.', 'Estate e inizio autunno; in quota la neve può restare fino a luglio', null, null, null, null, null),
  ('NO-4', 'bondhusvatnet', 'it', 'Lago Bondhusvatnet', 'Lago di montagna ai piedi del ghiacciaio Bondhusbrea, una lingua del Folgefonna che si specchia nell''acqua. Ci si arriva lungo una vecchia strada sterrata, costruita nell''Ottocento per portare a valle il ghiaccio.', 'A piedi da Sunndal, sul Maurangsfjord: circa 2 km di sterrato quasi pianeggiante dal parcheggio.', 'Da tarda primavera all''autunno', null, null, null, null, null),
  ('NO-4', 'baroniet-rosendal', 'it', 'Baronia di Rosendal', 'Piccolo castello del 1665, l''unica baronia mai esistita in Norvegia, con un giardino di rose e un parco ai piedi delle montagne dell''Hardanger.', 'A Rosendal, sulla riva sud dell''Hardangerfjord.', 'Apertura stagionale: giorni e orari da verificare sul sito', null, null, null, null, null),
  ('NO-4', 'langfoss', 'it', 'Cascata Langfoss', 'Cascata che scivola per oltre 600 metri lungo il fianco della montagna fino all''Åkrafjord, passando sotto la strada.', 'Area di sosta lungo la E134, nel comune di Etne.', 'Tutto l''anno; più acqua in primavera e a inizio estate', null, null, null, null, null),
  ('NO-4', 'molde', 'it', 'Molde', 'La «città delle rose», sul Romsdalsfjord: dal belvedere di Varden si vede un lungo orizzonte di cime oltre il fiordo. È una buona base per la Strada Atlantica.', 'Sulla E39; aeroporto e nave costiera.', 'Tutto l''anno', null, null, null, null, null),
  ('NO-4', 'romsdalsmuseet', 'it', 'Museo del Romsdal', 'Museo all''aperto nel centro di Molde, con decine di edifici tradizionali della regione e un edificio moderno per le mostre.', 'A Molde, a pochi minuti a piedi dal centro.', 'Edifici all''aperto soprattutto in estate: orari da verificare', null, null, null, null, null),
  ('NO-4', 'kristiansund', 'it', 'Kristiansund', 'Città costruita su alcune isole intorno al porto, storica capitale del baccalà (klippfisk). Tra un''isola e l''altra fa servizio un piccolo battello cittadino, il Sundbåten.', 'All''estremità nord della Strada Atlantica; aeroporto e nave costiera.', 'Tutto l''anno', null, null, null, null, null),
  ('NO-4', 'trollveggen', 'it', 'Trollveggen', 'La «parete dei troll», nella valle del Romsdal: con circa 1.000 metri di roccia, in parte strapiombante, è la parete verticale più alta d''Europa. Si guarda dal fondovalle.', 'Area di sosta e centro visitatori lungo la E136, a sud di Åndalsnes.', 'Tutto l''anno; centro visitatori stagionale', null, null, null, null, null),
  ('NO-4', 'rampestreken', 'it', 'Romsdalsgondolen e Rampestreken', 'Funivia aperta nel 2021 che dal centro di Åndalsnes sale al monte Nesaksla (circa 700 m), con vista sul Romsdalsfjord e sulle cime. Più in basso c''è Rampestreken, una passerella d''acciaio sospesa nel vuoto.', 'Stazione a valle nel centro di Åndalsnes, accanto alla stazione ferroviaria.', 'Orari della funivia da verificare; si ferma con vento forte', 'A piedi il sentiero per Rampestreken è molto ripido: con i bambini conviene salire in funivia.', null, null, null, null),
  ('NO-4', 'mardalsfossen', 'it', 'Cascata Mardalsfossen', 'Una delle cascate più alte d''Europa, nella valle di Eikesdalen. L''acqua è usata da una centrale idroelettrica e la cascata scorre solo in estate.', 'Da Eikesdalen: circa 2 km a piedi dal parcheggio.', 'La cascata è aperta solo per alcune settimane d''estate: date da verificare', 'Di solito l''acqua viene chiusa intorno al 20 agosto: da verificare.', null, null, null, null),
  ('NO-4', 'gamle-strynefjellsvegen', 'it', 'Vecchia strada dello Strynefjell', 'Strada turistica nazionale di 27 km tra Grotli e Videsæter, finita nel 1894: tratti sterrati, muretti e paracarri in pietra, laghi di montagna e neve ai lati fino a estate inoltrata.', 'Strada 258, alternativa alla strada 15 tra Stryn e Grotli; stretta, in parte sterrata.', 'Chiusa in inverno, di solito da ottobre a giugno: aperture da verificare', null, null, null, null, null),
  ('NO-4', 'oljemuseum', 'it', 'Museo norvegese del petrolio', 'Museo sul porto di Stavanger che racconta il petrolio e il gas del Mare del Nord: modelli di piattaforme, attrezzature e molte installazioni da provare, anche per i bambini.', 'Nel centro di Stavanger, sul porto.', 'Tutto l''anno; giorni e orari di apertura da verificare sul sito', null, null, null, null, null),
  ('NO-4', 'gamle-stavanger', 'it', 'Vecchia Stavanger', 'Quartiere di oltre 170 case bianche in legno del Settecento e dell''Ottocento, con strade acciottolate e giardini, sul lato ovest del porto.', 'Nel centro di Stavanger, a piedi dal porto.', 'Tutto l''anno', null, null, null, null, null),
  ('NO-4', 'hermetikkmuseum', 'it', 'Museo norvegese delle conserve', 'Museo in una vecchia fabbrica di sardine in scatola nella Vecchia Stavanger: mostra come si lavorava il pesce quando le conserve erano la principale industria della città.', 'Nella Vecchia Stavanger, a piedi dal porto.', 'Tutto l''anno; giorni e orari di apertura da verificare sul sito', null, null, null, null, null),
  ('NO-4', 'stavanger-domkirke', 'it', 'Cattedrale di Stavanger', 'La più antica cattedrale della Norvegia, costruita intorno al 1125: navata romanica e coro gotico.', 'Nel centro di Stavanger.', 'Apertura per le visite da verificare', null, null, null, null, null),
  ('NO-4', 'sverd-i-fjell', 'it', 'Sverd i fjell (Spade nella roccia)', 'Tre spade di bronzo alte circa 10 metri piantate nella roccia sulla riva dell''Hafrsfjord: ricordano la battaglia dell''872 che unì la Norvegia in un solo regno. Accanto c''è una spiaggetta.', 'A Møllebukta, sull''Hafrsfjord, circa 6 km a sud-ovest del centro di Stavanger.', 'Tutto l''anno', null, null, null, null, null),
  ('NO-4', 'jernaldergarden', 'it', 'Fattoria dell''età del ferro di Ullandhaug', 'Fattoria del periodo 350–550 d.C. ricostruita sulle fondamenta originali: case lunghe con il focolare acceso e attività per i bambini.', 'Sul colle di Ullandhaug, circa 3 km a sud del centro di Stavanger.', 'Apertura stagionale: giorni e orari da verificare sul sito', null, null, null, null, null),
  ('NO-4', 'flor-og-fjaere', 'it', 'Flor og Fjære', 'Giardino esotico con palme e fiori creato su un''isoletta dei fiordi davanti a Stavanger; la visita comprende il battello e un pasto.', 'Solo in battello da Stavanger, con prenotazione.', 'Solo in stagione, da maggio a settembre circa: date e prenotazione da verificare', null, null, null, null, null),
  ('NO-4', 'vitenfabrikken', 'it', 'Vitenfabrikken, centro della scienza di Sandnes', 'Centro della scienza con esperimenti da provare, mostre di tecnica e un planetario.', 'Nel centro di Sandnes, a sud di Stavanger.', 'Tutto l''anno; giorni e orari di apertura da verificare sul sito', null, null, null, null, null),
  ('NO-4', 'solastranden', 'it', 'Spiaggia di Sola', 'Spiaggia di sabbia lunga oltre 2 km, con dune, affacciata sul Mare del Nord: la prima delle lunghe spiagge dello Jæren.', 'A Sola, vicino all''aeroporto di Stavanger, circa 15 km dal centro.', 'Tutto l''anno', null, null, null, null, null),
  ('NO-4', 'utstein-kloster', 'it', 'Monastero di Utstein', 'Il monastero medievale meglio conservato della Norvegia, del Duecento, sull''isola di Klosterøy.', 'In auto da Stavanger, attraverso le gallerie sottomarine verso le isole a nord.', 'Apertura stagionale: giorni e orari da verificare sul sito', null, null, null, null, null),
  ('NO-4', 'manafossen', 'it', 'Cascata Månafossen', 'Cascata con un salto di 92 metri, la più alta del Rogaland, in fondo al Frafjord.', 'Dal parcheggio un sentiero breve ma ripido, con gradini di roccia e catene.', 'Da primavera ad autunno', 'Il sentiero è corto ma ripido e scivoloso se bagnato: i bambini vanno tenuti per mano.', null, null, null, null),
  ('NO-4', 'kjerag', 'it', 'Kjeragbolten', 'Il masso incastrato in una fenditura a quasi 1.000 metri sopra il Lysefjord, sul monte Kjerag.', 'A piedi da Øygardstøl, sopra Lysebotn: circa 10 km tra andata e ritorno, con tre salite ripide attrezzate con catene.', 'Estate; la strada per Øygardstøl è chiusa in inverno', 'Escursione lunga e ripida, con tratti esposti: non adatta a bambini di 5 e 8 anni.', null, null, null, null),
  ('NO-4', 'skudeneshavn', 'it', 'Skudeneshavn', 'Cittadina sulla punta sud dell''isola di Karmøy, con un centro storico di case bianche in legno dell''Ottocento tra i meglio conservati della Norvegia.', 'In fondo all''isola di Karmøy, a sud di Haugesund.', 'Tutto l''anno', null, null, null, null, null),
  ('NO-4', 'avaldsnes', 'it', 'Avaldsnes', 'La più antica sede reale della Norvegia, legata al re Harald Bellachioma: una chiesa in pietra del Duecento, il centro storico Nordvegen e una fattoria vichinga ricostruita su un isolotto.', 'Sull''isola di Karmøy, pochi chilometri a sud di Haugesund.', 'Centro e fattoria vichinga con orari stagionali da verificare', null, null, null, null, null),
  ('NO-4', 'kristiansand', 'it', 'Kristiansand', 'La città più grande del sud della Norvegia: centro a scacchiera, una spiaggia cittadina, il vecchio molo del pesce e, poco fuori, il grande zoo e parco di divertimenti.', 'Sulla E18 e sulla E39; treno, aeroporto e traghetti dalla Danimarca.', 'Tutto l''anno', null, null, null, null, null),
  ('NO-4', 'posebyen', 'it', 'Posebyen', 'Il quartiere vecchio di Kristiansand: isolati di basse case bianche in legno, sopravvissute agli incendi della città.', 'Nel centro di Kristiansand, nella parte nord-est della scacchiera.', 'Tutto l''anno', null, null, null, null, null),
  ('NO-4', 'kunstsilo', 'it', 'Kunstsilo', 'Museo d''arte aperto nel 2024 dentro un silo per il grano degli anni Trenta, sul porto di Kristiansand: ospita una grande collezione di arte moderna nordica.', 'Sul porto di Kristiansand, a piedi dal centro.', 'Tutto l''anno; giorni e orari di apertura da verificare sul sito', null, null, null, null, null),
  ('NO-4', 'kanonmuseum', 'it', 'Museo del cannone di Kristiansand', 'Batteria costiera tedesca della seconda guerra mondiale a Møvik, con uno dei più grandi cannoni terrestri rimasti al mondo.', 'A Møvik, circa 8 km a ovest del centro di Kristiansand.', 'Apertura stagionale: giorni e orari da verificare sul sito', null, null, null, null, null),
  ('NO-4', 'setesdalsbanen', 'it', 'Ferrovia storica del Setesdal', 'Ferrovia a scartamento ridotto con locomotive a vapore e carrozze in legno: resta in servizio turistico un tratto di circa 8 km lungo il fiume Otra, da Grovane.', 'Stazione di Grovane, a Vennesla, a nord di Kristiansand.', 'Solo in estate e in alcuni giorni: calendario da verificare', null, null, null, null, null),
  ('NO-4', 'mineralparken', 'it', 'Mineralparken', 'Parco a Evje con una mostra di minerali e cristalli allestita in gallerie scavate nella roccia e, all''aperto, giochi e attività per i bambini.', 'A Hornnes, vicino a Evje, lungo la strada 9 del Setesdal.', 'Solo in estate: date di apertura da verificare', null, null, null, null, null),
  ('NO-4', 'lindesnes-fyr', 'it', 'Faro di Lindesnes', 'Il faro sul punto più a sud della Norvegia continentale, dove nel 1656 fu acceso il primo faro del paese. È ancora in funzione e ospita il museo nazionale dei fari.', 'In fondo alla penisola di Lindesnes, a sud-ovest di Mandal.', 'Tutto l''anno; orari da verificare', null, null, null, null, null),
  ('NO-4', 'nidarosdomen', 'it', 'Cattedrale di Nidaros', 'La cattedrale medievale più a nord del mondo, costruita a partire dal 1070 sopra la tomba del re sant''Olav: è il santuario nazionale della Norvegia, con una facciata ovest coperta di statue.', 'Nel centro di Trondheim.', 'Tutto l''anno; orari delle visite e della torre da verificare', null, null, null, null, null),
  ('NO-4', 'erkebispegarden', 'it', 'Palazzo dell''arcivescovo', 'Residenza fortificata degli arcivescovi accanto alla cattedrale, tra i palazzi vescovili medievali meglio conservati d''Europa. Ospita un museo e i gioielli della corona norvegese.', 'Nel centro di Trondheim, a sud della cattedrale.', 'Tutto l''anno; giorni e orari di apertura da verificare sul sito', null, null, null, null, null),
  ('NO-4', 'gamle-bybro', 'it', 'Ponte vecchio e Bakklandet', 'Il ponte in legno con i portali rossi sul fiume Nidelva: da qui si vedono i magazzini colorati su palafitte. Dall''altra parte c''è Bakklandet, quartiere di casette in legno e caffè.', 'Nel centro di Trondheim, a pochi minuti dalla cattedrale.', 'Tutto l''anno', null, null, null, null, null),
  ('NO-4', 'kristiansten', 'it', 'Fortezza di Kristiansten', 'Fortezza del 1681 sulla collina a est del centro, con una bella vista su Trondheim, sul fiume e sul fiordo.', 'A piedi dal Ponte vecchio, in salita attraverso Bakklandet.', 'Area aperta tutto l''anno; interni solo in estate', null, null, null, null, null),
  ('NO-4', 'vitensenteret-trondheim', 'it', 'Centro della scienza di Trondheim', 'Centro della scienza con esperimenti da provare e un planetario, nell''ex sede della Banca di Norvegia.', 'Nel centro di Trondheim.', 'Tutto l''anno; giorni e orari di apertura da verificare sul sito', null, null, null, null, null),
  ('NO-4', 'rockheim', 'it', 'Rockheim', 'Museo nazionale della musica pop e rock norvegese, con molte sale interattive, in un vecchio magazzino del porto sormontato da un grande cubo luminoso.', 'Sul porto di Trondheim, vicino alla stazione.', 'Tutto l''anno; giorni e orari di apertura da verificare sul sito', null, null, null, null, null),
  ('NO-4', 'pirbadet', 'it', 'Pirbadet', 'Grande piscina coperta con parco acquatico sul porto di Trondheim: scivoli, vasca con le onde e vasche per i piccoli.', 'Sul porto di Trondheim, vicino alla stazione.', 'Tutto l''anno; orari da verificare', null, null, null, null, null),
  ('NO-4', 'munkholmen', 'it', 'Munkholmen', 'Isolotto nel fiordo davanti a Trondheim: è stato monastero, fortezza e prigione. Oggi è una meta estiva, con una spiaggetta e visite alla fortezza.', 'In battello dal centro di Trondheim (Ravnkloa).', 'Battello solo in estate: date e orari da verificare', null, null, null, null, null),
  ('NO-4', 'ringve', 'it', 'Museo della musica di Ringve', 'Museo nazionale della musica e degli strumenti musicali, in una villa storica sulla penisola di Lade, circondata da un giardino botanico.', 'A Lade, circa 4 km a nord-est del centro di Trondheim (autobus).', 'Tutto l''anno; giorni e orari di apertura da verificare sul sito', null, null, null, null, null),
  ('NO-4', 'sverresborg', 'it', 'Museo all''aperto di Sverresborg', 'Grande museo all''aperto del Trøndelag intorno ai resti del castello del re Sverre: fattorie, una stavkirke e un quartiere di vecchie case di Trondheim.', 'A Sverresborg, circa 3 km a ovest del centro di Trondheim (autobus).', 'Tutto l''anno; in estate più edifici aperti: orari da verificare', null, null, null, null, null),
  ('NO-4', 'stiklestad', 'it', 'Stiklestad', 'Il luogo della battaglia del 1030 in cui morì il re Olav, poi santo patrono della Norvegia: un centro culturale con mostre, una chiesa medievale e un museo all''aperto.', 'A Stiklestad, pochi chilometri a est di Verdal, lungo la E6 a nord di Trondheim.', 'Centro aperto tutto l''anno; museo all''aperto in estate: orari da verificare', null, null, null, null, null),
  ('NO-4', 'roros-kirke', 'it', 'Chiesa di Røros', 'La grande chiesa bianca in pietra del 1784 che domina la città mineraria, chiamata «l''ornamento della città»: con circa 1.600 posti è tra le più grandi della Norvegia.', 'Nel centro di Røros.', 'Apertura per le visite da verificare', null, null, null, null, null),
  ('NO-4', 'smelthytta', 'it', 'Smelthytta, museo di Røros', 'Il museo della città mineraria, nella fonderia ricostruita accanto alle colline di scorie: modelli in movimento mostrano come si estraeva e si fondeva il rame.', 'Nel centro di Røros, accanto al torrente.', 'Tutto l''anno; giorni e orari di apertura da verificare sul sito', null, null, null, null, null),
  ('NO-4', 'olavsgruva', 'it', 'Miniera di Olavsgruva', 'Miniera di rame visitabile nei dintorni di Røros: la visita guidata scende a circa 50 metri sotto terra, tra gallerie del Seicento e del Novecento.', 'A Storwartz, circa 13 km a est di Røros.', 'Visite guidate a orari fissi, più frequenti in estate: da verificare', 'In miniera ci sono circa 5 °C tutto l''anno: servono vestiti caldi e scarpe chiuse.', null, null, null, null),
  ('NO-4', 'namsskogan-familiepark', 'it', 'Park Nordica (Namsskogan Familiepark)', 'Parco per famiglie con gli animali del nord (orsi, lupi, linci, alci, volpi artiche) in grandi recinti nel bosco e alcune attrazioni per i bambini. Il parco, noto come Namsskogan Familiepark, oggi si chiama Park Nordica.', 'A Trones, lungo la E6 nel nord del Trøndelag.', 'Soprattutto in estate: date e orari da verificare', null, null, null, null, null),
  ('NO-4', 'torghatten', 'it', 'Torghatten', 'La montagna con il buco: una galleria naturale lunga circa 160 metri attraversa da parte a parte il monte sull''isola di Torget. Ci si sale a piedi e si può passare dall''altra parte.', 'In auto da Brønnøysund (circa 15 km); dal parcheggio un sentiero sistemato con gradini, circa 20–30 minuti in salita.', 'Da primavera ad autunno', null, null, null, null, null),
  ('NO-4', 'vegaoyan', 'it', 'Vega e l''arcipelago di Vegaøyan', 'Arcipelago di migliaia di isolotti al largo dell''Helgeland, patrimonio UNESCO per la tradizione di raccogliere il piumino degli edredoni, accuditi dagli isolani in casette costruite apposta.', 'In traghetto o battello veloce dalla zona di Brønnøysund (orari da verificare).', 'Estate', null, null, null, null, null),
  ('NO-4', 'de-syv-sostre', 'it', 'Le Sette Sorelle (Helgeland)', 'Catena di sette cime tra 900 e 1.072 metri, allineate sull''isola di Alsten, a sud di Sandnessjøen: si vedono bene dalla strada costiera e dal mare.', 'Lungo la strada costiera 17 nei dintorni di Sandnessjøen.', 'Tutto l''anno; le salite alle cime sono escursioni impegnative', null, null, null, null, null),
  ('NO-4', 'petter-dass-museet', 'it', 'Museo Petter Dass', 'Museo dedicato al sacerdote e poeta Petter Dass (1647–1707), ad Alstahaug: un edificio moderno incassato nella roccia, accanto alla chiesa medievale e alla vecchia canonica.', 'Ad Alstahaug, circa 20 km a sud di Sandnessjøen.', 'Tutto l''anno; giorni e orari di apertura da verificare sul sito', null, null, null, null, null),
  ('NO-4', 'svartisen', 'it', 'Ghiacciaio Svartisen', 'Il secondo ghiacciaio della Norvegia per estensione. La lingua di Engabreen scende fin quasi al livello del mare, sull''Holandsfjord.', 'Si vede dalla strada costiera 17 (area di sosta di Braset); per avvicinarsi c''è un battello sull''Holandsfjord e poi circa 3 km a piedi o in bicicletta.', 'Estate; battello con orari da verificare', 'Sul ghiaccio e sotto la fronte si va solo con una guida.', null, null, null, null),
  ('NO-4', 'saltfjellet-svartisen', 'it', 'Parco nazionale Saltfjellet–Svartisen', 'Grande parco nazionale a cavallo del circolo polare: dai ghiacciai dello Svartisen e dai fiordi a ovest fino agli altopiani aperti del Saltfjellet a est.', 'Dalla E6 sul Saltfjellet, dalla valle di Beiarn e dalla costa.', 'Estate e inizio autunno; in quota la neve può restare fino a luglio', null, null, null, null, null),
  ('NO-4', 'polarsirkelsenteret', 'it', 'Centro del Circolo Polare Artico', 'Centro visitatori sulla E6 nel punto in cui la strada attraversa il circolo polare, sull''altopiano del Saltfjellet a circa 680 metri: monumenti, una mostra e un negozio.', 'Sulla E6, circa 80 km a nord di Mo i Rana.', 'Aperto solo nella bella stagione: date da verificare', null, null, null, null, null),
  ('NO-4', 'gronligrotta', 'it', 'Grotta Grønligrotta', 'Grotta carsica nel marmo, con un torrente sotterraneo, esplorata dal 1914: si visita con una guida lungo un percorso illuminato.', 'Nella valle di Røvassdalen, circa 25 km a nord di Mo i Rana.', 'Visite guidate solo in estate: apertura da verificare', 'Dentro è freddo e umido, con scale e passaggi bassi: scarpe chiuse e giacca.', null, null, null, null),
  ('NO-4', 'rago', 'it', 'Parco nazionale di Rago', 'Piccolo parco nazionale selvaggio a est della E6: lastroni di granito, laghi e grandi cascate, al confine con i parchi svedesi.', 'Dal parcheggio di Lakshol, a nord di Fauske; i sentieri sono ripidi e poco segnati.', 'Estate', 'Terreno difficile, con tratti ripidi e guadi: non adatto a bambini piccoli.', null, null, null, null),
  ('NO-4', 'jektefartsmuseet', 'it', 'Museo delle navi da carico del Nordland', 'Museo aperto nel 2019 a Bodø intorno alla «Anna Karoline», l''ultima jekt rimasta: i velieri che portavano lo stoccafisso dal nord a Bergen.', 'A Bodøsjøen, pochi chilometri a est del centro di Bodø.', 'Tutto l''anno; giorni e orari di apertura da verificare sul sito', null, null, null, null, null),
  ('NO-4', 'hamsunsenteret', 'it', 'Centro Hamsun', 'Museo dedicato allo scrittore Knut Hamsun, cresciuto qui a Hamarøy, in una torre scura progettata dall''architetto Steven Holl.', 'A Presteid, nel comune di Hamarøy, poco fuori dalla E6.', 'Tutto l''anno; giorni e orari di apertura da verificare sul sito', null, null, null, null, null),
  ('NO-4', 'narvikfjellet', 'it', 'Cabinovia di Narvikfjellet', 'Cabinovia che dalla città di Narvik sale sulla montagna: dal ristorante in quota si vedono la città, l''Ofotfjord e le cime intorno.', 'Stazione a valle sopra il centro di Narvik.', 'Orari estivi da verificare', null, null, null, null, null),
  ('NO-4', 'henningsvaer-stadion', 'it', 'Campo da calcio di Henningsvær', 'Campo da calcio in erba sintetica su un isolotto di roccia in fondo al villaggio di Henningsvær, circondato dal mare e dalle rastrelliere per lo stoccafisso: famoso per le foto dall''alto.', 'In fondo a Henningsvær, a piedi dal centro del villaggio.', 'Tutto l''anno', null, null, null, null, null),
  ('NO-4', 'telegrafbukta', 'it', 'Telegrafbukta', 'Spiaggia e parco sulla punta sud dell''isola di Tromsø, molto frequentati in estate, con prati e vista sulle montagne di Kvaløya.', 'A sud del centro di Tromsø, vicino al museo universitario (autobus o a piedi lungo il mare).', 'Tutto l''anno', null, null, null, null, null),
  ('NO-4', 'blaisvatnet', 'it', 'Lago Blåisvatnet', 'Lago glaciale dall''acqua turchese ai piedi delle Alpi di Lyngen, alimentato dal ghiacciaio Lenangsbreen.', 'A piedi dal parcheggio di Sørlenangsbotn: circa 4 km a tratta, quasi in piano, con l''ultimo tratto su pietraia.', 'Estate', 'L''ultimo tratto tra i massi è lento con un bambino di 5 anni.', null, null, null, null),
  ('NO-4', 'ovre-dividal', 'it', 'Parco nazionale Øvre Dividal', 'Parco nazionale dell''interno del Troms, istituito nel 1971: valli di pini e betulle, altopiani e fauna del grande nord, lontano dalle strade.', 'Dalla valle di Dividalen, a sud di Bardufoss; dentro il parco solo sentieri.', 'Estate e inizio autunno; in quota la neve può restare fino a luglio', null, null, null, null, null),
  ('NO-4', 'reisa', 'it', 'Parco nazionale di Reisa', 'Parco nazionale lungo la valle e il canyon del fiume Reisa, con la cascata Mollisfossen, alta 269 metri. Si risale il fiume con le lunghe barche tradizionali.', 'Da Storslett lungo la valle di Reisadalen fino a Saraelv; poi in barca sul fiume o a piedi.', 'Estate; gite in barca da prenotare, da verificare', null, null, null, null, null),
  ('NO-4', 'alta', 'it', 'Alta', 'La città più grande del Finnmark, in fondo all''Altafjord: incisioni rupestri patrimonio UNESCO, la cattedrale dell''Aurora boreale e il canyon del fiume Alta nei dintorni.', 'Sulla E6; aeroporto.', 'Tutto l''anno', null, null, null, null, null),
  ('NO-4', 'alta-museum', 'it', 'Museo di Alta e incisioni rupestri', 'Migliaia di figure incise sulla roccia tra 7.000 e 2.000 anni fa (renne, alci, barche, scene di caccia), patrimonio UNESCO. Si vedono lungo passerelle in legno in riva al fiordo, accanto al museo.', 'A Hjemmeluft, circa 5 km a ovest del centro di Alta.', 'Museo tutto l''anno; le incisioni all''aperto si vedono solo senza neve', null, null, null, null, null),
  ('NO-4', 'nordlyskatedralen', 'it', 'Cattedrale dell''Aurora boreale', 'Chiesa del 2013 nel centro di Alta, rivestita di titanio, con un campanile a spirale che ricorda il movimento dell''aurora.', 'Nel centro di Alta.', 'Apertura per le visite da verificare', null, null, null, null, null),
  ('NO-4', 'tirpitz-museum', 'it', 'Museo Tirpitz', 'Piccolo museo di guerra a Kåfjord, il fiordo dove durante la seconda guerra mondiale era ancorata la corazzata tedesca Tirpitz.', 'A Kåfjord, lungo la E6 a ovest di Alta.', 'Solo in estate: apertura da verificare', null, null, null, null, null),
  ('NO-4', 'hammerfest', 'it', 'Hammerfest', 'Città sull''isola di Kvaløya, tra le più settentrionali del mondo, affacciata sul Mare di Barents.', 'Strada 94 dalla E6; aeroporto e nave costiera.', 'Tutto l''anno', null, null, null, null, null),
  ('NO-4', 'meridianstotten', 'it', 'Colonna del meridiano', 'Colonna del 1854 che segna l''estremo nord dell''Arco geodetico di Struve, la catena di misure con cui nell''Ottocento si calcolò la forma della Terra; è patrimonio UNESCO.', 'A Fuglenes, sul lato nord del porto di Hammerfest.', 'Tutto l''anno', null, null, null, null, null),
  ('NO-4', 'isbjornklubben', 'it', 'Club dell''orso polare', 'Piccola mostra sulla storia di Hammerfest e sulla caccia artica; ci si può iscrivere al club solo venendo qui di persona.', 'Nel centro di Hammerfest, vicino al porto.', 'Orari da verificare', null, null, null, null, null),
  ('NO-4', 'honningsvag', 'it', 'Honningsvåg', 'Cittadina di pescatori sull''isola di Magerøya, l''ultima prima di Capo Nord.', 'Sulla E69, attraverso la galleria sottomarina di Capo Nord; nave costiera.', 'Tutto l''anno', null, null, null, null, null),
  ('NO-4', 'gjesvaerstappan', 'it', 'Isole degli uccelli di Gjesværstappan', 'Isolotti alti e ripidi a ovest di Capo Nord, riserva naturale con una delle più grandi colonie di uccelli marini della Norvegia: pulcinelle di mare, sule, gazze marine e aquile di mare.', 'In barca dal villaggio di Gjesvær, sull''isola di Magerøya.', 'Gite in barca in estate: date da verificare', 'Gli uccelli lasciano le colonie nel corso di agosto: verificare prima di prenotare.', null, null, null, null),
  ('NO-4', 'stabbursdalen', 'it', 'Parco nazionale di Stabbursdalen', 'Parco nazionale a ovest del Porsangerfjord che protegge la pineta più settentrionale del mondo, lungo il fiume Stabburselva.', 'Dalla E6 a Stabbursnes, a nord di Lakselv, dove c''è anche un centro visitatori.', 'Estate e inizio autunno; in quota la neve può restare fino a luglio', null, null, null, null, null),
  ('NO-4', 'sapmi-park', 'it', 'Sápmi Park', 'Parco tematico sulla cultura sami a Karasjok: tende e capanne tradizionali, renne e un racconto multimediale sui miti sami.', 'Nel centro di Karasjok.', 'Soprattutto in estate: orari da verificare', null, null, null, null, null),
  ('NO-4', 'samiske-samlinger', 'it', 'Museo sami di Karasjok', 'Il principale museo di arte, cultura e storia sami, fondato nel 1972, con una parte all''aperto.', 'Nel centro di Karasjok.', 'Tutto l''anno; giorni e orari di apertura da verificare sul sito', null, null, null, null, null),
  ('NO-4', 'sametinget', 'it', 'Parlamento sami', 'La sede del parlamento dei sami della Norvegia, a Karasjok: un edificio in legno del 2000 con l''aula a forma di tenda tradizionale.', 'A Karasjok.', 'Visite guidate in alcuni orari: da verificare', null, null, null, null, null),
  ('NO-4', 'juhls', 'it', 'Galleria d''argento Juhls', 'Laboratorio e galleria di argenteria aperti nel 1959 a Kautokeino, in un edificio dalle forme insolite cresciuto negli anni: gioielli ispirati alla tradizione sami.', 'Poco fuori dal centro di Kautokeino.', 'Orari da verificare', null, null, null, null, null),
  ('NO-4', 'kirkenes', 'it', 'Kirkenes', 'Città di confine all''estremo nord-est, a pochi chilometri dalla Russia e dalla Finlandia; è il capolinea della rotta costiera.', 'Sulla E6; aeroporto e nave costiera.', 'Tutto l''anno', null, null, null, null, null),
  ('NO-4', 'grenselandmuseet', 'it', 'Museo della terra di confine', 'Museo di Kirkenes sulla storia di una regione di frontiera: la seconda guerra mondiale, le miniere e i rapporti con i vicini.', 'A Kirkenes, poco a sud del centro.', 'Tutto l''anno; giorni e orari di apertura da verificare sul sito', null, null, null, null, null),
  ('NO-4', 'grense-jakobselv', 'it', 'Grense Jakobselv', 'Piccolo villaggio alla foce del fiume che segna il confine con la Russia, sul Mare di Barents, con una cappella in pietra del 1869 e una spiaggia.', 'Circa 60 km di strada da Kirkenes.', 'Estate; la strada è chiusa in inverno', 'Zona di confine: vanno rispettati i cartelli e i divieti lungo il fiume.', null, null, null, null),
  ('NO-4', 'ovre-pasvik', 'it', 'Parco nazionale Øvre Pasvik', 'Lembo di taiga con pini secolari, laghi e paludi nella valle di Pasvik, dove vive l''orso bruno; nel parco si incontrano i confini di Norvegia, Finlandia e Russia.', 'Dalla valle di Pasvik, circa 100 km a sud di Kirkenes.', 'Estate (molte zanzare) e inizio autunno', null, null, null, null, null),
  ('NO-4', 'vardohus', 'it', 'Fortezza di Vardøhus', 'La fortezza più a nord del mondo: una piccola stella di bastioni del 1737 nella città di Vardø.', 'A Vardø, sull''isola di Vardøya, collegata alla terraferma da una galleria sottomarina.', 'Orari da verificare', null, null, null, null, null),
  ('NO-4', 'steilneset', 'it', 'Memoriale di Steilneset', 'Memoriale del 2011 per le 91 persone condannate per stregoneria nel Finnmark nel Seicento: un lungo corridoio sospeso di Peter Zumthor e un''installazione di Louise Bourgeois.', 'A Vardø, sulla riva vicino alla fortezza.', 'Tutto l''anno', null, null, null, null, null),
  ('NO-4', 'hornoya', 'it', 'Isola degli uccelli di Hornøya', 'Isolotto disabitato davanti a Vardø, il punto più a est della Norvegia: una riserva con decine di migliaia di uccelli marini che si guardano da vicino lungo un sentiero.', 'Breve traversata in barca dal porto di Vardø.', 'Barca solo in stagione: date da verificare', 'Gli uccelli lasciano la scogliera nel corso di agosto: verificare prima di andare.', null, null, null, null),
  ('NO-4', 'hamningberg', 'it', 'Hamningberg', 'Villaggio di pescatori abbandonato negli anni Sessanta, tra i pochi del Finnmark non distrutti nella seconda guerra mondiale, alla fine di una strada tra rocce frastagliate.', 'In fondo alla strada turistica di Varanger, circa 40 km oltre Vardø.', 'Estate; la strada è chiusa in inverno', null, null, null, null, null);
