insert into public.operators (release_id, operator_key, position, name, kind, url, sources, texts) values
  ('NO-4', 'hurtigruten', 0, 'Hurtigruten', 'nave_costiera', null, '[{"label":"Hurtigruten — Port-to-port (regole cabine, pasti, sconti bambini)","url":"https://www.hurtigruten.com/en-gb/practical-information/port-to-port","checkedAt":"2026-10-27"},{"label":"Hurtigruten — Prenotazione port-to-port","url":"https://www.hurtigruten.com/en/port-to-port","checkedAt":"2026-10-27"},{"label":"Hurtigruten — Piano di navigazione","url":"https://www.hurtigruten.com/en/sail-plan"}]'::jsonb, '{"it":{"facts":["Si può scegliere porto di imbarco e sbarco tra i 34 porti, con biglietto di sola andata o andata e ritorno.","Cabina facoltativa per viaggi sotto le 23 ore, obbligatoria oltre le 23 ore; suite non disponibili per il port-to-port.","Pasti non inclusi: pensione completa, mezza pensione o à la carte acquistabili in prenotazione o a bordo.","Bambini fino a 5 anni gratis, da 6 a 17 anni sconto del 75% sul solo biglietto (non su cabina, pasti ed extra).","Trasporto auto: non chiarito sulla pagina port-to-port, da verificare con il servizio clienti."]}}'::jsonb),
  ('NO-4', 'havila', 1, 'Havila', 'nave_costiera', null, '[{"label":"Havila Voyages — FAQ port-to-port","url":"https://www.havilavoyages.com/faq/port-to-port","checkedAt":"2026-10-27"},{"label":"Havila Voyages — Round voyage (ordine dei porti)","url":"https://havilavoyages.com/voyages/round-voyage-bergen-kirkenes-bergen","checkedAt":"2026-10-27"}]'::jsonb, '{"it":{"facts":["Port-to-port tra 34 porti; check-in fino a 15 minuti prima della partenza.","Cabina facoltativa: per i tratti notturni si può scegliere poltrona o cabina.","Pasti non inclusi: pacchetti colazione/pranzo/cena acquistabili online (sconto 15% indicato) o caffetteria a bordo.","Veicoli aggiungibili separatamente dove disponibile.","Prenotazione al massimo 6 mesi prima della partenza: per agosto 2027 si apre indicativamente a febbraio 2027.","Sconti per bambini: non riportati nella FAQ consultata, da verificare."]}}'::jsonb);
